function cachedMeasureTextWidth(ctx: CanvasRenderingContext2D, text: string): number {
  if (window.devicePixelRatio !== lastDevicePixelRatio) {
    // This cache is no longer valid!
    measureTextCache.clear()
    lastDevicePixelRatio = window.devicePixelRatio
  }
  if (!measureTextCache.has(text)) {
    measureTextCache.set(text, ctx.measureText(text).width)
  }
  return measureTextCache.get(text)!
}

function sameTimeBars() {
  let height = 150,
    width = 960,
    margin: Margin = {
      top: 20,
      left: 25,
      right: 25,
      bottom: 20,
    }

  let container = null,
    chartWidth = 0,
    chartHeight = 0

  function chart(selection) {
    const svg: Selection<SVGElement, null, null, null> = selection.append('svg')
    svg.attr('width', width).attr('height', height)

    container = svg
      .append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`)

    chartWidth = width - (margin.left + margin.right)
    chartHeight = height - (margin.top + margin.bottom)

    container
      .selectAll('g')
      .data(data[dataType])
      .join('g')
      .attr('transform', (d, i) => `translate(${(chartWidth / 4) * i}, 0)`)
      .each(
        bar().options({
          height: chartHeight,
          width: chartWidth / 4,
        }),
      )

    selection.call(
      styleObj({
        position: 'relative',
      }),
    )

    const controls = selection.append('div').call(
      styleObj({
        position: 'absolute',
        top: '0',
        left: '0',
      }),
    )

    controls
      .append('select')
      .on('change', function () {
        console.log(
          'hiya',
          this,
          this.selectedIndex,
          this.options[this.selectedIndex].value,
        )
        dataType = this.options[this.selectedIndex].value
        chart.redraw()
      })
      .selectAll('option')
      .data(Object.keys(data))
      .join('option')
      .text(d => d)
  }

  chart.redraw = function () {
    container.selectAll('g').remove()

    container
      .selectAll('g')
      .data(data[dataType])
      .join('g')
      .attr('transform', (d, i) => `translate(${(chartWidth / 4) * i}, 0)`)
      .each(
        bar().options({
          height: chartHeight,
          width: chartWidth / 4,
        }),
      )
  }

  chart.options = function (options: ChartOptions) {
    Object.assign(margin, options.margin)
    width = options.width || width
    height = options.height || height
    return chart
  }

  return chart
