function getRoutingInfo(routeRes: any) {
  const routeData = JSON.parse(JSON.stringify(routeDetails.routeData));

  const students: Student[] = routeDetails.students
    ? routeDetails.students.map((u: StudentResponse) => u.userData)
    : [];

  const routingInfo = routeRes;

  // const routingInfo = JSON.parse(JSON.stringify(routeRes))

  const routeStops = routeData.stops.filter((stop: Stop | Via) => {
    return stop.__typename !== "via";
  });

  routeStops.forEach((stop: Stop, index: number) => {
    const assignedStudents: any = [];
    students.forEach((student: Student) => {
      student.districts[0].schools ?.forEach((school: SchoolUser) => {
        school.routes ?.forEach((route: RouteUser) => {
          if (
            route.homeStop === stop.stopId &&
            route.routeId === routeData.id
          ) {
            assignedStudents.push(student);
          }
        });
      });
    });
    if (routeData.startLocation) {
      routingInfo.leg[index + 1] = {
        ...routingInfo.leg[index + 1],
        students: assignedStudents,
        stopName:
          stop.address.street !== " "
            ? stop.address.street
            : formatAddress(stop.address),
        stopNote: stop.notes ? stop.notes : null,
      };
    } else {
      routingInfo.leg[index] = {
        ...routingInfo.leg[index],
        students: assignedStudents,
        stopName:
          stop.address.street !== " "
            ? stop.address.street
            : formatAddress(stop.address),
      };
    }
  });

  if (routeData.startLocation) {
    routingInfo.leg[0] = {
      ...routingInfo.leg[0],
      students: [],
      stopName:
        routeData.startLocation.address.street !== " "
          ? routeData.startLocation.address.street
          : formatAddress(routeData.startLocation.address),
      stopNote: null,
    };
  }
  if (routeData.endLocation) {
    routingInfo.leg[routingInfo.leg.length] = {
      students: [],
      stopName:
        routeData.endLocation.address.street !== " "
          ? routeData.endLocation.address.street
          : formatAddress(routeData.endLocation.address),
      stopNote: null,
    };
  }

  return routingInfo;
}

function fromFile(file: string, options?: IWaveOptions, fromFileOptions?: IFromFileOptions): { deactivate: () => void } {
  const parsedOptions = {
    ...defaultOptions,
    ...(options || {}),
  };

  const { callback, width, height, format, drawRate } = {
    width: window.innerWidth,
    height: window.innerHeight,
    format: 'png',
    drawRate: 20, //ms
    callback: () => null,
    ...fromFileOptions,
  }

  checkGenerator(parsedOptions.type);

  const imageFormat = `image/${format}`;
  const canvas = createVirtualCanvas(width, height);
  const audio: HTMLAudioElement = new Audio(file);
  const audioCtx: AudioContext = new AudioContext();
  const analyser = audioCtx.createAnalyser();
  const source = audioCtx.createMediaElementSource(audio);
  analyser.fftSize = 2 ** 10;
  const bufferLength = analyser.frequencyBinCount;
  const tempData: Uint8Array = new Uint8Array(bufferLength);
  let getWave: ReturnType<typeof setTimeout> = null;

  source.connect(analyser);
  audio.addEventListener('loadedmetadata', () => audio.play().then());

  const playListener = () => {
    let frameCount = 1;
    getWave = setInterval(() => {
      analyser.getByteFrequencyData(tempData);
      visualize(tempData, canvas, parsedOptions, frameCount++);
      callback(canvas.toDataURL(imageFormat));
    }, drawRate);
  };

  const endedListener = () => {
    if (audio.currentTime === audio.duration && tempData !== undefined) {
      clearInterval(getWave);
    }
  };

  audio.addEventListener('play', playListener);
  audio.addEventListener('ended', endedListener);

  return {
    deactivate: () => {
      audio.removeEventListener('play', playListener);
      audio.removeEventListener('ended', endedListener);
      clearInterval(getWave);
      audioCtx.close().then();
      clearCanvas(canvas)
      callback(canvas.toDataURL(imageFormat));
    }
  };
}

