function findInsertionIndex(
  index: number,
  array: Array<{ index: number }>,
  low: number = 0,
  high: number = array.length - 1
): number {
  if (!array.length) {
    return 0
  }

  while (low <= high) {
    const mid = low + ((high - low) >> 1)
    const value = array[mid].index

    if (index < value) {
      high = mid - 1
    } else if (index > value) {
      low = mid + 1
    } else {
      return mid
    }
  }

  return low
}

