function verifyOrigin(
  vel: OriginVerifier | OriginVerifier[],
  origin: string,
): boolean {
  if (typeof vel === "string") {
    return vel === origin;
  } else if (vel instanceof RegExp) {
    return origin.match(vel) != null;
  } else if (typeof vel === "function") {
    return vel(origin);
  } else {
    for (const v of vel) {
      if (verifyOrigin(v, origin)) {
        return true;
      }
    }
  }
  return false;
}

