        })
        .from(sequencesEvents)
        .leftJoin(sequences, eq(sequencesEvents.sequenceId, sequences.id))
        .orderBy(desc(sequencesEvents.date))
        .offset((pagination.page - 1) * pagination.perPage)
        .limit(pagination.perPage)
        .all();
