function WildCopy(src: Uint8Array, src_0: number, dst: Uint8Array, dst_0: number, dst_end: number) {
    let len = dst_end - dst_0;
    while (len >= 8) {
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        len -= 8;
    }
    while (len >= 4) {
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        dst[dst_0++] = src[src_0++];
        len -= 4;
    }
    while (len-- > 0) {
        dst[dst_0++] = src[src_0++];
    }
    return len;
}

