function countLetters(s: string, count: number): number {
    const counter = new Map<string, number>()

    // Build map.
    for (const c of s) {
        let cur = counter.get(c)
        if (cur === undefined) {
            cur = 0
        }
        counter.set(c, cur + 1)
    }

    // Check count.
    let counts = 0
    for (const v of counter.values()) {
        if (v === count) {
            counts++
        }
    }

    return counts
}

