function GETDELIVERYTIME_ID(storage: string, deliveryTime: string): string {

    let result = '';
    if (Number(storage) > 0) {
        result = "01";      // 跟舒经理核实，现货产品传最小时间单位
    } else {
        if (StringUtils.isEmpty(deliveryTime)) {
            result = '21';
        } else if (Number(deliveryTime) <= 9) {
            result = '0' + deliveryTime;
        }
        else if (Number(deliveryTime) <= 15) {
            result = deliveryTime;
        } else if (Number(deliveryTime) <= 21) {
            result = '21';
        } else if (Number(deliveryTime) <= 31) {
            result = '31';
        } else {
            result = '32';
        }
    }
    return result;
}

async function getVectors(): Promise<vectors> {
  const message: string = await Deno.readTextFile(Deno.args[4]);
  let strings: string[] = message.split(EOL.CRLF);
  if (detect(strings[0]) === EOL.LF) strings = message.split(EOL.LF).filter(string => string !== '');
  const vectors: vectors = strings.map((string: string) =>
    string.split(' ').map(el => {
      if (+el !== 1 && +el !== 0) throw new Error(ERROR.WRONG_FILE_CONTENTS);
      return +el === 1 ? 1 : 0;
    })
  );
  return vectors;
}

