function consumeTopic(topicToConsume, groupId, fromBeginning = false, regexLiteral = '', messageFormat: string, avroSchema: string = "") {
  return (dispatch: Dispatch, getState: GetState) => {
    let consumer = getState().kafka.client.consumer({ groupId: groupId });
    const regex = new RegExp(regexLiteral);
    consumer.connect()
      .then(async () => {
        dispatch(consumerStart(consumer, topicToConsume, regexLiteral, messageFormat, avroSchema));
        await consumer.subscribe({ topic: topicToConsume, fromBeginning: fromBeginning });
        await consumer.run({
          eachMessage: async ({ topic, partition, message }) => {
            const value = message.value && message.value.toString();
            let matched = false;
            if (regexLiteral) {
              matched = value.match(regex) !== null
            }
            await dispatch(messageConsume({
              key: message.key.toString(),
              value: value,
              offset: message.offset,
              timeStamp: message.timestamp,
              topic: topic,
              partition: partition,
              matched: matched
            }));
          },
        })
      });
  };
}

function wrapInLoader<T>(fn: AppAction<Promise<T>>): AppAction<Promise<T>> {
    return (dispatch, getState) => {
        dispatch(setLoadingState(true));
        const endLoading = () => dispatch(setLoadingState(false));

        return fn(dispatch, getState, undefined).then(
            (resp) => {
                endLoading();

                return resp;
            },
            (resp) => {
                endLoading();

                return Promise.reject(resp);
            },
        );
    };
}

function closest(element: Element, selector: string) {
  if (window['Element'] && !Element.prototype.closest) {
    Element.prototype.closest = function(s) {
      let matches = (this.document || this.ownerDocument).querySelectorAll(s),
        i,
        el = this;
      do {
        i = matches.length;
        while (--i >= 0 && matches.item(i) !== el) {}
      } while (i < 0 && (el = el.parentElement));
      return el;
    };
  }

  return element.closest(selector);
}

