function useLocalStorage<T = any>(name: string, initialState: any = null) {
  let prefixedName = PREFIX_LOCAL_STORAGE.toUpperCase() + name.toUpperCase();
  const [x, setX] = useState<T>(() => {
    const item = localStorage.getItem(prefixedName);
    if (item) {
      return JSON.parse(item);
    }
    if (typeof initialState == "function") {
      return initialState();
    }
    return initialState;
  });

  useEffect(() => {
    localStorage.setItem(prefixedName, JSON.stringify(x));
  }, [x, prefixedName]);

  return [x, setX];
}

async function getPokemons(obj: any, args: IGetPokemonsArgs, context: any, info: any): Promise<{pokemons: IPokemons[]} | boolean> {
    try {
        let {url} = args
        const limit = 20
        if(!url) {
            url = `https://pokeapi.co/api/v2/pokemon?limit=${limit}&offset=0`
        }
        const response: AxiosResponse<IAPIGetPokemons>  = await axios({
            method: 'GET',
            url
        })

        if(response.status === 200) {
            let {results, ...rest} = response.data
            const pokemons: IPokemons[] = results.map(result => {
                return {
                  ...result,
                  id: parseInt(
                    result.url.split('https://pokeapi.co/api/v2/pokemon/')[1]
                  )
                }
              })
              return {
                ...rest,
                pokemons
            }
        }
        return false
    }
    catch(e) {
        console.log(e)
        return false
    }
}

