    let path = filePathNormalized.replace(configAppNormalized, '').replace(/^\//,'').replace(/^\\/,'');
    arguments[0] = Config.APP_BASE + slash(path) + `?${Date.now()}`;
    return slash(plugins.inject.transform.apply(plugins.inject.transform, arguments));
  };
}

