function mapShape<T, S>(f: (arg: T) => S, v: Shape<T>): Shape<S> {
  switch (v.shapeType) {
    case "Circle":
      return mapCircle(f, v);
    case "Ellipse":
      return mapEllipse(f, v);
    case "Equation":
      return mapEquation(f, v);
    case "Image":
      return mapImage(f, v);
    case "Line":
      return mapLine(f, v);
    case "Path":
      return mapPath(f, v);
    case "Polygon":
      return mapPolygon(f, v);
    case "Polyline":
      return mapPolyline(f, v);
    case "Rectangle":
      return mapRectangle(f, v);
    case "Text":
      return mapText(f, v);
    case "Group":
      return mapGroup(f, v);
  }
}

