function replace<T>(
  head: LinkedListNode<T> | null,
  oldValue: T,
  newValue: T
): LinkedListNode<T> | null {
  let currentNode = head;

  while (currentNode) {
    if (currentNode.value === oldValue) {
      currentNode.value = newValue;
      break;
    }
    currentNode = currentNode.next;
  }

  return head;
}

