function getMatchingReactNativeSemVerForReactNativeMacOSVersion(
  rnmacVersion: string,
) {
  const validVersion = semver.valid(rnmacVersion);
  if (validVersion) {
    const major = semver.major(validVersion);
    const minor = semver.minor(validVersion);
    if (major === 0 && minor >= 60) {
      return `^${major}.${minor}`;
    }
  }
  return 'unknown';
}

