async function put(id: number, params: Partial<Event>) {
  try {
    await getConnection().transaction(async (tm) => {
      const eventRepository = tm.getRepository(Event);
      await getById(id, params.timelineId, eventRepository);
      await eventRepository.save({ id, ...params });
      const event = await eventRepository.findOneOrFail(id, {
        relations: ["row", "category"],
      });

      if (event.category && event.category.timelineId !== event.timelineId) {
        throw {
          message: "Event and category does not belong to the same timeline",
          statusCode: ErrorCode.BadRequest,
        };
      }

      if (event.row && event.row.timelineId !== event.timelineId) {
        throw {
          message: "Event and row does not belong to the same timeline",
          statusCode: ErrorCode.BadRequest,
        };
      }

      return event;
    });
  } catch (error) {
    if (error.statusCode) throw error;
    throw {
      message: "Event data is invalid or missing required fields",
      statusCode: ErrorCode.BadRequest,
    };
  }
}

function score(nodes: Node[]): number {
    let node = nodes.find(n => n.value == 0)
    for (let [i, result] = [0, 0]; ; ++i, node = node.next) {
        if (i == 1000 || i == 2000)
            result += node.value
        else if (i == 3000)
            return result + node.value
    }
}

function opAppend<T>(...iterablesToAppend: Iterable<T>[]): PipeFn<T, T> {
    function _(i: Iterable<T>): Iterable<T>;
    function _(i: AsyncIterable<T>): AsyncIterable<T>;
    function _(i: Iterable<T> | AsyncIterable<T>): Iterable<T> | AsyncIterable<T> {
        return isAsyncIterable(i) ? opAppendAsync(...iterablesToAppend)(i) : opAppendSync(...iterablesToAppend)(i);
    }
    return _;
}

