function flattenFragments(root: Fiber): Fiber | Fiber[] {
  if (root.elementName === '#text') return root;
  if (root.elementName === 'Fragment')
    return (
      (root.props.children as Fiber[])
        ?.map((child) => ({ ...child, parent: root.parent }))
        ?.map(flattenFragments)
        ?.flat(Infinity) ?? []
