function getCirclePercentage(
  point: Point,
  center: Point,
  extraRotation: number = 0,
) {
  let angle =
    Math.atan2(point.y - center.y, point.x - center.x) + extraRotation;

  if (angle < 0) {
    angle += Math.PI * 2;
  }

  return angle / (Math.PI * 2);
}

