function node<T extends godot.Node>(target: T, property: string, descriptor?: any) {
	const key = `$onready:${property}`;
	const path_key = `${property} `; // <-- a space at the end
	descriptor = descriptor || {};
	descriptor.set = function(v) { this[key] = v; };
	descriptor.get = function() {
		let v = this[key];
		if (!v) {
			v = (this as godot.Node).get_node(this[path_key]);
			this[key] = v;
		}
		return v;
	};
	godot.register_property(target, path_key, { type: godot.TYPE_NODE_PATH });
	return descriptor;
}

function handleGroup(data: any[], group: any[]): any {
    let groups: any = new Map();
    let groupKeys: any = Object.values(group);
    if (groupKeys.length > 1) {
        return groupHelper(data, groupKeys);
    }
    for (let i of data) {
        let keyValues: any[] = [];
        for (let key of groupKeys) {
            keyValues.push(i[key.toString()]);
        }
        for (let val of keyValues) {
            if (groups.has(val.toString())) {
                let a: any[] = groups.get(val.toString());
                a.push(i);
                groups.set(val, a);
            } else if (!groups.has(val.toString())) {
                let b: any[] = [];
                b.push(i);
                groups.set(val, b);
            }
        }
    }
    let result: any[] = [];
    for (let g of groups.values()) {
        result.push(Object.values(g));
    }
    return result;
}

