function changeVectorTileLayout(
    vector: ILayer,
    layout: ILayout,
    document: IDocument
) {
    const layers = document.layers;
    if (!layers) {
        return undefined;
    }

    layers.map((layer) => {
        if (layer.type === LayerType.GroupLayer) {
            if (layer.children) {
                layer = loopGroupProp(vector.id, "layout", layout, layer);
            }
        } else {
            if (layer.id === vector.id) {
                if (layer.type === LayerType.RasterTile) {
                    layer.layout = layout;
                }
            }
        }
        return layer;
    });

    return layers;
}

