function changeVectorTileFilter(
    vector: ILayer,
    filter: IFilter,
    document: IDocument
) {
    const layers = document.layers;
    if (!layers) {
        return undefined;
    }

    layers.map((layer) => {
        if (layer.type === LayerType.GroupLayer) {
            if (layer.children) {
                layer = loopGroupProp(vector.id, "filter", filter, layer);
            }
        } else {
            if (layer.id === vector.id) {
                if (layer.type === LayerType.VectorTile) {
                    layer.filter = filter;
                }
            }
        }
        return layer;
    });

    return layers;
}

function createITunesService(
  network: NetworkService,
  {
    searchEndpoint = "https://itunes.apple.com/search",
    lookupEndpoint = "https://itunes.apple.com/lookup",
    proxy = false
  }: ITunesServiceFactoryOpts = {}
): ITunesService {
  const gateway = createITunesGateway();
  return {
    async searchPodcasts(
      term: string,
      params: Partial<ITunesSearchParams> = {}
    ) {
      const queryParams = {
        ...params,
        term: encodeURIComponent(term).replace("%20", "+"),
        media: "podcast"
      };
      const parsed = (await getParsedResponse(
        searchEndpoint,
        queryParams,
        network,
        proxy
      )) as ITunesResponse;
      return parsed.results.map(r => gateway.read(r) as PodcastResponseData);
    },

    async searchAuthors(
      term: string,
      params: Partial<ITunesSearchParams> = {}
    ) {
      const queryParams = {
        ...params,
        term: encodeURIComponent(term).replace("%20", "+"),
        media: "podcast",
        entity: "podcastAuthor"
      };
      const parsed = (await getParsedResponse(
        searchEndpoint,
        queryParams,
        network,
        proxy
      )) as ITunesResponse;
      return parsed.results.map(r => gateway.read(r) as AuthorResponseData);
    },

    async getPodcastByID(ID: number) {
      const parsed = (await getParsedResponse(
        lookupEndpoint,
        { id: ID },
        network,
        proxy
      )) as ITunesResponse;
      if (parsed.results.length === 0 || !isTrack(parsed.results[0])) {
        throw new ApplicationError(
          "Podcast not found",
          "ITunes Service could not find any podcast matching the given ID: " +
            ID,
          ITunesErrors.PODCAST_NOT_FOUND
        );
      }

      return gateway.read(parsed.results[0]) as PodcastResponseData;
    },

    async getAuthorByID(ID: number) {
      const parsed = (await getParsedResponse(
        lookupEndpoint,
        { id: ID },
        network,
        proxy
      )) as ITunesResponse;
      if (parsed.results.length === 0 || !isArtist(parsed.results[0]))
        throw new ApplicationError(
          "Author not found",
          "ITunes Service could not find any author matching the given ID: " +
            ID,
          ITunesErrors.AUTHOR_NOT_FOUND
        );
      return gateway.read(parsed.results[0]) as AuthorResponseData;
    }
  };
}

function oneHot_(
    indices: Tensor|TensorLike, depth: number, onValue = 1, offValue = 0,
    dtype: DataType = 'int32'): Tensor {
  if (depth < 2) {
    throw new Error(`Error in oneHot: depth must be >=2, but it is ${depth}`);
  }
  const $indices = convertToTensor(indices, 'indices', 'oneHot', 'int32');

  const inputs: OneHotInputs = {indices: $indices};
  const attrs: OneHotAttrs = {dtype, depth, onValue, offValue};

  return ENGINE.runKernel(
      OneHot, inputs as unknown as NamedTensorMap,
      attrs as unknown as NamedAttrMap);
}

