function parseParams(str):any {
            var match,
                result = {},
                arrayRegex = new XRegExp("^\\[(?<values>(.*?))\\]$"),
                regex = new XRegExp(
                    "(?<name>[\\w-]+)" +
                        "\\s*:\\s*" +
                        "(?<value>" +
                        "[\\w-%#]+|" +		// word
                        "\\[.*?\\]|" +		// [] array
                        '".*?"|' +			// "" string
                        "'.*?'" +			// '' string
                        ")\\s*;?",
                    "g"
                );

            while ((match = regex.exec(str)) != null) {
                var value:any = match.value.replace(/^['"]|['"]$/g, '');
                if (value != null && arrayRegex.test(value)) {
                    var m:{ values:any
                    } = arrayRegex.exec(value);
                    value = m.values.length > 0 ? m.values.split(/\s*,\s*/) : [];
                }
                result[match.name] = value;
            }

            return result;
        }

function getRules(
  rules: WhitespaceRules,
  node: TSESTree.TypeNode,
): WhitespaceRule {
  const scope = node?.parent?.parent;

  if (isTSFunctionType(scope) || isTSConstructorType(scope)) {
    return rules.arrow;
  } else if (isIdentifier(scope)) {
    return getIdentifierRules(rules, scope);
  } else if (isClassOrTypeElement(scope)) {
    return rules.property;
  } else if (isFunction(scope)) {
    return rules.returnType;
  }
  return rules.colon;
}

