function readFile(file, enc, callback) {
    // Skip reading contents if read option says so
    const read = resolveOption(options.read, file)
    if (!read) {
      return callback(null, file)
    }

    // Don't fail to read a directory
    if (file.isDirectory()) {
      return onRead(null)
    }

    // Process symbolic links included with `resolveSymlinks` option
    if (file.stat && file.stat.isSymbolicLink()) {
      return readSymbolicLink(file, onRead)
    }

    // Read and pass full contents
    const buffer = resolveOption(options.buffer, file)
    if (buffer) {
      return readBuffer(file, options, onRead)
    }

    // Don't buffer anything - just pass streams
    return readStream(file, options, onRead)

    // This is invoked by the various readXxx modules when they've finished
    // reading the contents.
    function onRead(readErr) {
      if (readErr) {
        return callback(readErr)
      }
      callback(null, file)
    }
  }

function extractNestedUnionTypes(
  { type, name = "" }: TypeNode,
  typeStore: TypeNode[]
): Array<TypeNode<UnionType>> {
  switch (type.kind) {
    case TypeKind.NULL:
    case TypeKind.BOOLEAN:
    case TypeKind.STRING:
    case TypeKind.FLOAT:
    case TypeKind.DOUBLE:
    case TypeKind.INT32:
    case TypeKind.INT64:
    case TypeKind.DATE:
    case TypeKind.DATE_TIME:
    case TypeKind.BOOLEAN_LITERAL:
    case TypeKind.STRING_LITERAL:
    case TypeKind.NUMBER_LITERAL:
      return [];
    case TypeKind.TYPE_REFERENCE:
      return extractNestedUnionTypes(
        { name, type: resolveType(type, typeStore) },
        typeStore
      );
    case TypeKind.OBJECT:
      return flatten(
        type.properties.map(property =>
          extractNestedUnionTypes(
            {
              type: property.type,
              name: name + "." + property.name
            },
            typeStore
          )
        )
      );
    case TypeKind.ARRAY:
      return extractNestedUnionTypes({ type: type.elements, name }, typeStore);
    case TypeKind.UNION:
      return flatten([
        {
          name,
          type
        },
        ...type.types.map((possibleType, index) =>
          extractNestedUnionTypes(
            {
              type: possibleType,
              name: `${name}[${index}]`
            },
            typeStore
          )
        )
      ]);
    default:
      throw assertNever(type);
  }
}

