function getArrayOfWordsFor(text: string): string[] {
  const formated = text.split(" ").map((item) =>
    item
      .toLocaleLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "")
  );
  return formated;
