function combineMiddlewares<T = any, P = any>(middlewares:IMiddleware<T, P>[]):IMiddleware<T, P>
{
    // 处理middlewares异常
    middlewares = (middlewares || []).filter(middleware=>middleware instanceof Function);
    const middleware:IMiddleware<T, P> = (context, next)=>{
        return runMiddlewares(middlewares, context, next);
    };
    middleware["subMiddlewares"] = middlewares;
    return middleware;
}

