function findInTree (tree: Tree | undefined, cargo: number): number | undefined {
  const _findInTree = (_tree: Tree | undefined, _cargo: number): number | undefined => {
    if (!_tree) {
      return
    } else if (_cargo === _tree.cargo) {
      return _tree.cargo
    } else if (_cargo < _tree.cargo) {
      return _findInTree(_tree.left, _cargo)
    } else {
      return _findInTree(_tree.right, _cargo)
    }
  }

  const foundCargo = _findInTree(tree, cargo)

  console.log(`Found cargo => ${foundCargo}`)

  return foundCargo
}

function wave(
  fn: TrigFunction,
  p = 1000,
  min = -1,
  max = 1,
  o = 0,
): WaveFunction {
  /**
   * peak amplitude (not peak-to-peak amplitude)
   * @see https://en.wikipedia.org/wiki/Amplitude
   */
  const amp = (max - min) / 2;

  /**
   * radians per period (angular frequency)
   * @see https://en.wikipedia.org/wiki/Angular_frequency
   */
  const rpp = ππ / p;

  return (t: number) => {
    const ots = o + t; // offset timestamp
    return amp * (1 + fn(ots * rpp)) + min;
  };
}

