function reducer(state = initialState, action: wishes.Actions): State {
  switch (action.type) {
    case wishes.GET_WISHES_SUCCESS: {
      return Object.assign({}, state, {wishes: action.payload});
    }
    case wishes.ADD_WISH_SUCCESS: {
      return Object.assign({}, state, {
        wishes: [...state.wishes, action.payload]
      });
    }
    case wishes.DELETE_WISH_SUCCESS: {
      const newWishes = state.wishes.filter(
        (wish) => wish.id !== action.payload.id
      );

      return Object.assign({}, state, {
        wishes: newWishes
      });
    }
    case wishes.DELETE_ALL_WISHES_SUCCESS: {
      const newWishes = [];

      return Object.assign({}, state, {
        wishes: newWishes
      });
    }
    default:
      return state;
  }
}

function setupReducerActions<State>(
  reducerActions: OriginalReducerActions<State>,
  getState: () => State,
): [Observable<Action<State>>, TriggerActions] {
  const actions: TriggerActions = {}
  const reducers: Observable<Action<State>>[] = []

  Object.keys(reducerActions).forEach((actionName) => {
    const reducer$ = new Subject<Action<State>>()
    reducers.push(reducer$)

    const reducer = reducerActions[actionName]

    actions[actionName] = (params: any) => {
      const nextState = reducer(getState(), params)

      reducer$.next({
        reducerAction: { params, actionName, nextState },
        originalActionName: actionName,
      })
    }
  })

  return [merge(...reducers), actions]
}

function loginUser(req: Request, res: Response) {
  // login admins and customers with email

  var body = req.body;

  User.findOne({ tx_email: body.tx_email })
    .populate('id_company')
    .then(userDB => {

      if (!userDB) {
        return res.status(400).json({
          ok: false,
          msg: "Usuaro o Contraseña incorrecta."
        });
      }

      if (userDB.bl_social) {
        return res.status(400).json({
          ok: false,
          msg: "Para esa cuenta ingrese con el botón de " + userDB.tx_platform
        });
      }

      if (!bcrypt.compareSync(body.tx_password, userDB.tx_password)) {
        return res.status(400).json({
          ok: false,
          msg: "Contraseña o usuario incorrecto."
        });
      }

      if (!userDB.bl_active && (userDB.id_role === 'ADMIN_ROLE' || userDB.id_role === 'CUSTOMER_ROLE')) {
        return res.status(400).json({
          ok: false,
          msg: "El usuario no fué activado."
        });
      }



      // Si llego hasta acá, el user y la contraseña son correctas, creo el token

      // rompo la referencia con assign() y uso toObject() para usar extraer del objeto
      // la data que está en userDB._doc con un getter
      let newUser: any = Object.assign({}, userDB.toObject());
      // Le quito tx_company_welcome para evitar problemas con caracteres de 2 bytes 
      // al decodificar con atob() en el frontend
      newUser.id_company = 'eliminado solo para el token';
      newUser.tx_password = ":)";
      var token = Token.getJwtToken({ newUser });

      userDB.tm_lastlogin = new Date();
      if (userDB.id_role === 'CUSTOMER_ROLE' && body.bl_admin) {
        // el usuario esta registrado como cliente pero intenta loguearse como un comercio
        // si llega la petición es porque acepta convertir el ROL a ADMIN en el frontend.
        userDB.id_role = 'ADMIN_ROLE';
      }


      userDB.save().then(async () => {

        userDB.tx_password = ":)";

        let home;
        switch (userDB.id_role) {
          case 'WAITER_ROLE':
            home = '/waiter/home';
            break;
          case 'ADMIN_ROLE':
            home = '/admin/home';
            break;
          case 'CUSTOMER_ROLE':
            home = '/public/tickets';
            break;
        };


        // ADMIN
        res.status(200).json({
          ok: true,
          msg: 'Usuario logueado correctamente',
          token: token,
          user: userDB,
          menu: await obtenerMenu(userDB),
          home
        });

      }).catch((err) => {
        return res.status(500).json({
          ok: false,
          msg: 'Error al actualizar la fecha de login',
          errors: err
        });
      })

    }).catch((err) => {
      return res.status(500).json({
        ok: false,
        msg: "Error al buscar un user",
        errors: err
      });

    })


}

