function processPartTwo(numbers: number[]) {
    console.time("part two");
    let count = 0;
    let ip = 0;
    while (ip < numbers.length) {
        count++;
        if (numbers[ip] >= 3) {
            numbers[ip] -= 1;
            ip += numbers[ip] + 1;
        } else {
            numbers[ip] += 1;
            ip += numbers[ip] - 1;
        }
    }
    console.timeEnd("part two");
    return count;
