function approachLinear(a: number, b: number, factor: number)
{
    if (a < b)
        return Math.min(a + factor, b);
    else if (a > b)
        return Math.max(a - factor, b);
    return b;
}

async function exitWeightedPool(
  signer: Signer,
  poolId: string,
  senderAddress: string,
  receipientAddress: string,
  vaultAddress: string,
  tokens: string[],
  minAmountsOut: BigNumber[],
  toInternalBalance = false,
  exitKind: WeightedPoolExitKind = WeightedPoolExitKind.EXACT_BPT_IN_FOR_TOKENS_OUT,
  maxBPTIn: BigNumber,
  tokenIndex?: number
): Promise<ContractTransaction> {
  // Balancer V2 vault allows userData as a way to pass props through to pool contracts.
  const userData = getUserData(exitKind, minAmountsOut, maxBPTIn, tokenIndex);

  const exitRequest = {
    assets: tokens,
    minAmountsOut,
    userData,
    toInternalBalance,
  };

  const vaultContract = Vault__factory.connect(vaultAddress, signer);
  const exitReceipt = await vaultContract.exitPool(
    poolId,
    senderAddress,
    receipientAddress,
    exitRequest
  );

  return exitReceipt;
}

