function generateTerminalRScript(acslProgram: AcslProgram, outputs: string[])
{
  let codeBlocks: ICodeBlock[] = [];
  codeBlocks.push(...acslProgram.codeBlocks.filter(c => isStatement(c) && !c.isConstant));
  codeBlocks.push(...acslProgram.dynamicSection.codeBlocks.filter(c => isStatement(c) && !c.isConstant));
  codeBlocks.push(...acslProgram.terminalSection.codeBlocks);

  let computationData = codeBlocks.map(c => codeBlockToCode(c, unitIndent + unitIndent + unitIndent, false));
  let terminalEndSectionComments =
    generateCommentBlock(acslProgram.terminalSection.comments, CommentPlacement.EndSection, "#", unitIndent + unitIndent + unitIndent);
  let terminal = tmplTerminal({
    computationData: computationData,
    terminalEndSectionComments: terminalEndSectionComments,
    lastOutput: 0 == outputs.length ? "???" : outputs[outputs.length - 1]
  });
  return terminal;
}

async function autocommand(
    msg: Message,
    bot: Bot,
    client: Client,
    config: Config
) {
    if (!config.plugin.auto_command.includes(msg.info.contextId)) {
        return false;
    }
    const content = msg.info.content.replace(`${msg.prefix} `, '');
    if (/[+\-/*{};]|=>/.test(content)) {
        const result = await RunEval(content);
        client.hardReply(result, msg);
        return true;
    }
    if (/ or /.test(content)) {
        const result = chooseFunction(msg.quotedArgsList);
        if (result) {
            client.send(result, msg);
            return true;
        }
    }
    const data = await mdnSearch(bot, content);
    if (!data) {
        return false;
    }

    const terms = content.split(/\s|\./);
    const matches = terms.filter((term) =>
        data.title.toLowerCase().includes(term.toLowerCase())
    ).length;

    if (matches / terms.length > 0.4) {
        client.hardReply(
            bot.htmldecode(client.link(data.title, data.url)),
            msg
        );
        return true;
    }
    return false;
}

