function getTwitterFollowers(accoutName: string): number {
    const url = `https://mobile.twitter.com/${accoutName}`;
    const postheader: HttpHeaders = {
      timeout: "50000",
    };
    const parameters: URLFetchRequestOptions = {
      headers: postheader,
      method: "get",
      muteHttpExceptions: true,
    };
    const html: string = UrlFetchApp.fetch(url, parameters).getContentText(
      "UTF-8"
    );
    // curlで取得したHTMLの中から文字列を取得。その文字列をChrome Dev toolsでこねこねして考えた正規表現。
    const counts = html.match(
      /\/followers">[<>\w\s=/"]*statnum">([\d,]+)<\/div>/
    );
    if (counts === null) {
      Logger.log("cannot parse twitter follower");
      return -1;
    } else if (counts.length < 2) {
      Logger.log("unexpected parse result on twitter %s", counts);
      return -1;
    }
    return Number(counts[1].replace(/,/g, ""));
  }

async function verify(publicKey: CryptoKey, credential: PublicKeyCredential): Promise<boolean> {
    const { clientDataJSON, attestationObject } = credential.response
    if (attestationObject) {
        const decodedAttestationObject = decode(attestationObject) as AttestationObject
        const {
            attStmt: { sig },
            authData,
        } = decodedAttestationObject
        const clientDataJsonHash = await crypto.subtle.digest('SHA-256', clientDataJSON)
        return crypto.subtle.verify(
            {
                name: 'ECDSA',
                hash: 'SHA-256',
            },
            publicKey,
            sig,
            concatenate(authData, clientDataJsonHash),
        )
    }
    // fallback
    return Promise.resolve().then(() => true)
}

