async function partition(
  arr: Collection<Bar>,
  low: number,
  high: number,
  counter: Counter
) {
  const pivot = arr[high].value;
  let i = low;
  for (let j = low; j < high; j++) {
    if (arr[j].value <= pivot) {
      if (arr[j].value != arr[i].value) {
        await toHighlight(arr[i], arr[j]);
        arr.swap(i, j);
        counter.steps++;
      }
      i++;
    }
    toDefault(...arr);
    counter.steps++;
  }
  arr.swap(i, high);
  counter.steps++;
  return i;
}

