function lex(input: string) {
  let result
  const tokens = []
  const parser = validToken()

  while(
    (result = parser.parse(input) as Token)
  ) {
    if(!result.success) {
      throw new Error(`lexical parse error：expected ${result.expected}, actual ${result.actual}`)
    }
    // 不记录无用的 token
    TokenType.WHITESPACE === result.type || tokens.push(result)
    input = result.rest!

    if(result.type === TokenType.EOF) {
      break
    }
  }

  return tokens
}

function abortable<T>(abort:AbortController):OperatorFunction<T,T> {
    return (upstream)=>{
        return new Observable((observer)=>{
            const handler = ()=>{
                unsub.unsubscribe();
                observer.error('ABORTED');
                abort.signal.removeEventListener('abort',handler);
            }
            const unsub = upstream.subscribe({
                next:(v)=>{
                    observer.next(v);
                },
                error:(e)=>{
                    observer.error(e);
                },
                complete: ()=>{
                    observer.complete();
                    abort.signal.removeEventListener('abort',handler);
                }
            });
            abort.signal.addEventListener('abort',handler);
        });
    }
}

