  let res = {} as any

  for (let className in input) {
    res[className] = {}

    let propNames = Object.keys(schema[className])
    for (let propName of propNames) {
      res[className][propName] = []
    }

    for (let entry of input[className]) {
      for (let propName of propNames) {
        res[className][propName].add(entry[propName])
      }
    }


  }

  return res
