function generateMathOp(name: string): (b: IPy_Number) => IPy_Number | typeof NIError {
  return eval(`(function() { return function(b) {
      var a = this,
        bType = b.getType(),
        aType = a.getType(),
        typeDiff = aType - bType;
      if (bType > ${enums.Py_Type.COMPLEX}) {
        // b is not a number.
        return NIError;
      } else if (typeDiff > 0) {
        // a is wider than b
        b = widenTo(b, aType);
      } else if (typeDiff < 0) {
        // b is wider than a
        a = widenTo(a, bType);
      }
      return a.${name}(b);
    }
  })()`);
}

