function buildDaysArray(currentDate: Date = new Date()): Array<number> {
  const daysInCurrentMonth = numberOfDaysInMonth(
    currentDate.getMonth() + 1,
    currentDate.getFullYear()
  );
  let previousMonth = currentDate.getMonth() - 1;
  const year =
    previousMonth > 0
      ? currentDate.getFullYear()
      : currentDate.getFullYear() - 1;
  previousMonth = previousMonth < 0 ? 11 : previousMonth;
  const daysOfPreviousMonth = numberOfDaysInMonth(previousMonth, year);
  let firstDayOfMonth = new Date(
    currentDate.getFullYear(),
    currentDate.getMonth(),
    1
  ).getDay();
  firstDayOfMonth = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;
  return [
    ...fillArray(firstDayOfMonth, daysOfPreviousMonth, true).reverse(),
    ...fillArray(daysInCurrentMonth),
    ...fillArray(13)
  ].slice(0, 42);
}

function getMediaQuery(breakpoints?: Dict, mapper = toMediaQuery) {
  const _breakpoints = breakpoints ?? { sm: "40em", md: "52em", lg: "64em" }

  const asArray = objectKeys(_breakpoints)
    .map((key) => _breakpoints[key])
    .sort((a, b) => a - b)
    .map(mapper)

  const asObject = objectKeys(_breakpoints).reduce((result, point) => {
    result[point] = mapper(_breakpoints[point])
    return result
  }, {} as Dict)

  return { asArray, asObject }
}

