function parts(model: any, prop_remap, parts_def?): RequestHandler {
    if (!parts_def) {
        parts_def = prop_remap;
        prop_remap = {id: 'id'};
    }

    return (req, res, next) => {
        var parts_wanted = arr_filter((req.query.parts || '').split(',')),
            expand_wanted = arr_filter((req.query.expand || '').split(',')),
            bad_parts = [],
            queries = [];

        // check for invalid parts first
        each(parts_wanted, (part: string) => {
            if (!(part in parts_def)) {
                bad_parts.push(part);
            }
        });

        if (bad_parts.length) {
            next(new BadRequestError(ERR_MSG_INVALID_PARTS(bad_parts)));
            return;
        }

        // mian
        queries.push(model.findOne(build_query(prop_remap, req.params, {
            paranoid: false
        })).then(tag('main')));

        // parts
        each(parts_wanted, (part: string) => {
            var query = null,
                model = parts_def[part][0],
                prop_remap = parts_def[part][1],
                meta = parts_def[part][2] || {};

            if (meta.expand && includes(expand_wanted, part)) {
                query = model.findAll(build_query(prop_remap, req.params))
                    .then(results => {
                        var model = meta.expand[0],
                            remap = meta.expand[1];

                        results = Array.isArray(results) ? results : [results];

                        return q.all(map(results, val =>
                            model.findOne(build_query(remap, <SDict>val))
                                .then(stamp_meta('relationship', val))))
                                    .then(tag(part));
                    });
            } else if (meta.instead) {
                query = new Promise((resolve, reject) => {
                    var instead: QueryResultsModelMeta = {},
                        user_id = req.user.id,
                        checks = [];

                    if (meta.instead.count) {
                        checks.push(new Promise((resolve, reject) => {
                            model.findAndCountAll(build_query(prop_remap, req.params))
                                .then(count => {
                                    instead.count = count.count;
                                    resolve();
                                });
                        }));
                    }

                    if (meta.instead.includes_me) {
                        checks.push(new Promise((resolve, reject) => {
                            if (!user_id) {
                                instead.includes_me = false;
                                resolve();
                            } else {
                                model.findOne(build_query(prop_remap, req.params, {
                                    where: { user_id }
                                })).then(row => {
                                    instead.includes_me = !!row;
                                    resolve();
                                });
                            }
                        }));
                    }

                    return Promise.all(checks).then(() => q.when({})
                        .then(stamp_meta('instead', instead))
                        .then(tag(part))
                        .then(resolve));
                });
            } else {
                query = model.findAll(build_query(prop_remap, req.params))
                    .then(tag(part));
            }

            queries.push(query);
        });

        // combine `main` and `parts` into a single response object
        error_handler(res, q.all(queries)
            .then(results => {
                response_handler(res)(reduce(parts_wanted, (body, part: string) => {
                    body[part] = (<Tag>(find(results, {tag: part}) || {})).val;
                    return body;
                }, (<Tag>find(results, {tag: 'main'})).val));
            })
        );
    };
}

function makeSimpleReducer<State extends {}>(reducerName: string, initialState: State) {
    const actions = mapValues(initialState, (propertyFromState, key: keyof State) => {
        const creatorReducer = makeActionCreatorWithReducerWithPrefix<State, State[typeof key]>(
            `UPDATE_${key.toUpperCase()}`,
            (state, newValue) => {
                return assign({}, state,
                    {[key]: newValue}
                );
            }
        );
        return creatorReducer(reducerName) as any;
    }) as {
        [P in keyof State]: {
            actionCreator: ActionCreator<State[P]>;
            reducer: StateTypeReducer<State, State[P]>;
        }
    };
    const reset = makeActionCreatorWithReducerWithPrefix<State, null>(
        `RESET`,
        () => {
            return initialState;
        }
    )(reducerName);
    const setAll = makeActionCreatorWithReducerWithPrefix<State, State>(
        `SET_ALL`,
        (state, newValue) => {
            return newValue;
        }
    )(reducerName);
    const set = makeActionCreatorWithReducerWithPrefix<State, Partial<State>>(
        `SET`,
        (state, newStateValues) => {
            return assign({}, 
                state,
                newStateValues
            );
        }
    )(reducerName);
    return {
        actions: assign({}, 
            getCreators(assign({}, actions, {reset, setAll, set})),
        ),
        reducer: createReducer<State>(initialState, assign({}, actions, {reset, setAll, set})),
    };
}

