function arrow(x1, y1, x2, y2) {
  var t = Math.PI / 6;

  // d is the length of the arrowhead line
  var d = 8;

  // l is the length of the line AB = sqrt((x1-x0)^2 + (y1-y0)^2)
  var dx = x2 - x1,
    dy = y2 - y1;
  var l = Math.sqrt(dx * dx + dy * dy);

  var cost = Math.cos(t);
  var sint = Math.sin(t);
  var dl = d / l;

  var x = x2 - (dx * cost - dy * sint) * dl;
  var y = y2 - (dy * cost + dx * sint) * dl;

  var context = [];
  context.push('M');
  context.push(x2);
  context.push(y2);
  context.push('L');
  context.push(x);
  context.push(y);

  cost = Math.cos(-t);
  sint = Math.sin(-t);

  x = x2 - (dx * cost - dy * sint) * dl;
  y = y2 - (dy * cost + dx * sint) * dl;

  // context.push('L');
  context.push(x);
  context.push(y);

  context.push('Z');
  return context.join(' ');
}

