function charts(state:CGroupsState, action:ActionLocalMetrics):CGroupsState {
    if(action.type == '@@local-query/metrics') {
        let index = {}
        let result = new Map()
        action.metrics.values.sort((x, y) => {
            let xs = x[0].state;
            let ys = y[0].state;
            if(xs < ys) return -1;
            if(xs > ys) return 1;
            return 0;
        })
        for(let met of action.metrics.values) {
            let chunks = met[0].state.split('.');
            let item = chunks.pop();
            let base = chunks.join('.');

            let value = met[1].value
            let metricname = met[0].metric;
            let key = met[0].state + metricname;

            if(key in index) {
                let {metric, itemobj} = index[key];
                metric.total += value
                itemobj.value += value
                itemobj.text = FORMAT[metricname](itemobj.value)
            } else {
                let state = result.get(base)
                if(!state) {
                    state = {
                        duration: { items: [], total: 0 },
                        count: { items: [], total: 0 },
                    }
                    result.set(base, state)
                }
                let metric = state[metricname]
                let itemobj = {
                    title: item,
                    value: value,
                    text: FORMAT[metricname](value),
                    color: COLORS[metric.items.length],
                }
                metric.items.push(itemobj)
                metric.total += value
                index[key] = {metric, itemobj}
            }
        }
        return result;
    }
    return state;
}

function imul(a: number, b: number) {
	var ah  = (a >>> 16) & 0xffff;
	var al = a & 0xffff;
	var bh  = (b >>> 16) & 0xffff;
	var bl = b & 0xffff;
	// the shift by 0 fixes the sign on the high part
	// the final |0 converts the unsigned value into a signed value
	return ((al * bl) + (((ah * bl + al * bh) << 16) >>> 0)|0);
    }

