  // do the further processes such as emitting an event to broadcast which module is loaded
  // to its subscribers.
  //
  // we concat the registering logic after the original code of the modules, this manner brings the
  // benefits that we will not being required to deal with the variation of the source-maps
  return `
${originalSource}
;((typeof(window)!=='undefined'?window:global)["${NS}"]["${store}"]).push(["${id}", function () {
  var mod = require(${originalModule});
  return mod;
}]);
`;
}

function levelOrderBottom(root: TreeNode | null): number[][] {
  let res: number[][] = [];
  if(!root) return res;
  const traverse = (node: TreeNode | null, step: number) => {
    if(node) {
      if(!res[step]) res[step] = [];
      res[step].push(node.val);
      traverse(node.left, step + 1);
      traverse(node.right, step + 1);
    }
  }
  traverse(root, 0);
  return res.reverse();
}

function createDataFromGameObject(gameObject: GameObject): Data_GameObject {
    const json: Data_GameObject = {};
    if (gameObject.id) {
        json.id = gameObject.id;
    }
    if (gameObject.children) {
        json.children = [];
        for (let child of gameObject.children) {
            const dataChild = createDataFromGameObject(child);
            json.children.push(dataChild);
        }
    }
    if (gameObject._scripts) {
        json.scripts = [];
        for (let script of gameObject._scripts) {
            const scriptName = script.constructor.name;
            if (scriptName === 'HitTestScript') {
                continue;
            }
            const serilizedData = {
                scriptName: script.constructor.name
            };
            const serilizeableKeys = script['__proto__'].serilizeableKeys;
            if (serilizeableKeys) {
                for (let item of serilizeableKeys) {
                    serilizedData[item.key] = script[item.key];
                }
            }
            json.scripts.push(serilizedData);

        }
    }
    return json;
}

async function lastCommitFromOwlBotPostProcessor(
  owner: string,
  repo: string,
  prNumber: number,
  octokit: Octokit
): Promise<boolean> {
  const commitMessages: Array<string> = [];
  for await (const response of octokit.paginate.iterator(
    octokit.rest.pulls.listCommits,
    {
      pull_number: prNumber,
      owner,
      repo,
      per_page: 100,
    }
  )) {
    for (const {commit} of response.data) {
      commitMessages.push(commit.message);
    }
  }
  const message = commitMessages[commitMessages.length - 1];
  return message.includes(OWL_BOT_POST_PROCESSOR_COMMIT_MESSAGE_MATCHER);
}

