function _scrollTop(element: EventTarget, map: ScrollMap<number>): ko.types.event.Switch {

    let before = 0,
        _downTemp = [], _upTemp = [],       // 한번 호출된 핸들러는 반복호출되지 않게 배열에 담아둔다.
        index,

        handler = () => {
            let {pageYOffset: scrollY, pageXOffset: scrollX} = window,
                isDown = before < scrollY;


            // ① 스크롤 다운
            if (isDown) {
                map.target.forEach(v => {


                    if (v < before || scrollY < v) return;

                    index = _downTemp.indexOf(v);

                    if (index === -1) {
                        map.onscrollDown(v, scrollY, scrollX);
                        _downTemp.push(v);
                        if ((index = _upTemp.indexOf(v)) !== -1)
                            _upTemp.splice(index, 1);
                    }
                });
            }

            // ② 스크롤 업
            else {
                map.target.forEach(v => {

                    if (v > before || scrollY > v) return;

                    index = _upTemp.indexOf(v);

                    if (index === -1) {
                        map.onscrollUp(v, scrollY, scrollX);
                        _upTemp.push(v);
                        if ((index = _downTemp.indexOf(v)) !== -1)
                            _downTemp.splice(index, 1);
                    }
                });
            }

            before = scrollY;

        };

    return _bind(element, 'scroll', handler).on();
}

