    let vec = new THREE.Vector3();
    if (d1 <= d2) {
        vec.copy(points[0]);
    } else {
        vec.copy(points[points.length - 1]);
    }

    for (let ppp of points) {
        ppp.sub(vec);
    }

    let curve3 = new THREE.CatmullRomCurve3(points);
    curve3.arcLengthDivisions = curve.arcLengthDivisions;

