function isInstagramURL(url: string) {
  // 参考：
  // https://github.com/itteco/iframely/blob/245043afd1698d88f1ed05c6b7b075148aca1841/plugins/domains/instagram.com.js
  const regexes = [
    /^https?:\/\/(?:www.)?instagram\.com\/(?:[a-zA-Z0-9_-]+\/)?(?:p|tv)\/([a-zA-Z0-9_-]+)\/?/i,
    /^https?:\/\/instagr\.am\/(?:[a-zA-Z0-9_-]+\/)?p\/([a-zA-Z0-9_-]+)/i,
    /^https?:\/\/instagram\.com\/(?:[a-zA-Z0-9_-]+\/)?(?:p|tv)\/([a-zA-Z0-9_-]+)$/i
  ]
  const isInstagramURL = regexes.some(regex => regex.test(url))

  return isInstagramURL
}

function copyConfigs(srcPath: string, outPath: string) {
		return new Promise<void>(async (resolve, reject) => {
			let files = await fs.readdir(srcPath);
			files = files.filter((file) => file.endsWith('json'));

			let pending = files.length;
			let done = 0;

			if (!pending) resolve();

			files.forEach((file) => {
				let dest = Path.resolve(outPath, file);
				file = Path.resolve(srcPath, file);

				fs.copyFile(file, dest)
					.catch(reject)
					.then(() => {
						log.ok(`Copied '${file}' -> '${dest}'`);
						if (++done === pending) resolve();
					});
			});
		});
	}

function registerFormatter(context: ExtensionContext, languageId: string) {
    context.subscriptions.push(languages.registerDocumentFormattingEditProvider(languageId, {
        provideDocumentFormattingEdits: (document, options, token) => {
            const r = allOf(document);
            return format(document, r, options)
                .then(txt => [TextEdit.replace(r, txt)])
                .catch(report);
        }
    }));
    context.subscriptions.push(languages.registerDocumentRangeFormattingEditProvider(languageId, {
        provideDocumentRangeFormattingEdits: (document, range, options, token) => {
            let begin = new Position(range.start.line, 0);
            let end = range.end.translate(0, Number.MAX_VALUE);
            let r = document.validateRange(new Range(begin, end));
            return format(document, r, options)
                .then(txt => [TextEdit.replace(r, txt)])
                .catch(report);

        }
    }));
}

function escapeTableName(table: Partial<NSDatabase.ITable> | string) {
  let items: string[] = [];
  let tableObj = typeof table === 'string' ? <NSDatabase.ITable>{ label: table } : table;
  tableObj.database && items.push(`[${tableObj.database}]`);
  tableObj.schema && items.push(`[${tableObj.schema}]`);
  items.push(`[${tableObj.label}]`);
  return items.join('.');
}

function applyTo(target : any) {
  _.mixin(target, Hooks);

  const allHooks = Object.keys(hookTypes).concat(Object.keys(hookAliases));
  for (const hook of allHooks) {
    target[hook] = function(name, callback) {
      return this.addHook(hook, name, callback);
    };
  }
}

