function exec(...args: Array<string>) {
    const command = args.join(' ');

    return new Promise(((resolve, reject) => {
        const result = spawn(command, { shell: true, stdio: 'inherit' });
        result.on('error', reject);
        result.on('close', (code) => code === 0 ? resolve(true) : reject());
    }));
}

function promisifiedAuth(
  context: RequestContext,
  strategy: passport.Strategy,
  options?: AuthenticateOptions,
) {
  return new Promise<AuthViewer>((resolve, reject) => {
    const done = (err: Error, user: Viewer | null, _info: any) => {
      //console.log("done", err, user);
      if (err) {
        reject(err);
      } else {
        resolve(user);
      }
    };
    options = options || {};
    let authMethod = passport.authenticate(strategy.name!, options, done);
    return authMethod(
      context.request,
      context.response,
      (err?: Error | null) => {
        console.error("err", err);
      },
    );
  });
}

async function pipeAsync<T extends NodeJS.WritableStream>(source: Readable, destination: T): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        source.pipe(destination)
            .on('error', () => reject())
            .on('finish', () => resolve());
    });
}

function addMinutes(prefix: string, offset: number, time: InputHours): EntryTime | ExitTime {
  let m = time[`${prefix}M`] + offset;
  let h = time[`${prefix}H`];

  while (m < 0) {
    m += MIN_IN_HOUR;
    h--;
  }
  while (m > MIN_IN_HOUR) {
    m -= MIN_IN_HOUR;
    h++;
  }

  return {
    [`${prefix}H`]: h,
    [`${prefix}M`]: m,
  } as EntryTime | ExitTime;
}

function pointInRect(testPoint: Point, rect: Rectangle): boolean {
  const rectArea = areaOfRect(rect);

  if (rectArea === 0) {
    return false;
  }

  const triangles = rect.map((curPoint, i) => {
    const nextPoint = rect[(i + 1) % 4];
    return [testPoint, curPoint, nextPoint];
  });

  const trianglesArea = triangles.reduce(
    (prev, triangle) => prev + areaOfTriangle(triangle),
    0
  );

  return fix(trianglesArea) == fix(rectArea);
}

