function unfoldChunksLoop<S, R, E, A>(
  s: S,
  f: (s: S) => T.Effect<R, E, O.Option<Tp.Tuple<[Chunk.Chunk<A>, S]>>>
): C.Channel<R, unknown, unknown, unknown, E, Chunk.Chunk<A>, unknown> {
  return C.unwrap(
    T.map_(
      f(s),
      O.fold(
        () => C.unit,
        ({ tuple: [as, s] }) => C.chain_(C.write(as), () => unfoldChunksLoop(s, f))
      )
    )
  )
}

