function cssToTheme(css: string, sourceFilePath: string): Theme {
	const o = cssParse(css, {
		silent: false,
		source: sourceFilePath,
	});

	if (!o?.stylesheet?.rules?.length) throw new Error(`Invalid CSS color file: ${sourceFilePath}`);

	// Need "as any" because outdated TS definition file

	const rootRule = o.stylesheet.rules[0];
	if (!rootRule.selectors.includes(':root')) throw new Error('`:root` rule not found');

	const declarations: any[] = rootRule.declarations;

	const output: any = {};
	for (const declaration of declarations) {
		if (declaration.type !== 'declaration') continue; // Skip comment lines
		output[formatCssToThemeVariable(declaration.property)] = declaration.value;
	}

	return output;
}

function cliToArray(cliCommand: string): string[][] {
  const lines = cliCommand.split('\n')
    .map(s => s.trim())
    .map(cliToArrayOne)
    .filter(notUndefined)
    .filter(a => a.length)
  const result = []
  let currentCommand: string[] = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line[line.length - 1] !== '\\') {
      currentCommand = currentCommand.concat(line)
      //@ts-ignore
      result.push(currentCommand)
      currentCommand = []
    }
    else {
      currentCommand = currentCommand.concat(line.slice(0, line.length - 1))
    }
  }
  return result
}

