function scientific(a: IBigFloat): string {
  if (is_zero(a)) {
    return "0";
  }
  a = normalize(a);
  let s = String(
    JSBI.LT(a.coefficient, BIGINT_ZERO) ? -a.coefficient : a.coefficient
  );
  const e = a.exponent + s.length - 1;
  if (s.length > 1) {
    s = s.slice(0, 1) + "." + s.slice(1);
  }
  if (e !== 0) {
    s += "e" + e;
  }
  if (JSBI.LT(a.coefficient, BIGINT_ZERO)) {
    s = "-" + s;
  }
  return s;
}

