function FormatDate({format: formato, value}: Props): string {
  let valueAuxiliar;
  let infos;
  let data = '';
  let hora = '';
  let dia = '';
  let mes = '';
  let ano = '';

  try {
    value = value.replace('T', ' ');
    valueAuxiliar = value.split(' ');
    data = valueAuxiliar[0];
    hora = valueAuxiliar[1] == undefined ? '00:00' : valueAuxiliar[1];

    infos = data.split('');  
    if (value.indexOf('.') != -1) {
      infos = data.split('.');
    }

    if (value.indexOf('/') != -1) {
      infos = data.split('/');
    }

    if (value.indexOf('-') != -1) {
      infos = data.split('-');
    }

    if (infos[2].length == 2) {
      dia = infos[2];
      ano = infos[0];
    } else if (infos[2].length == 4) {
      dia = infos[0];
      ano = infos[2];
    }

    mes = infos[1];
    data = `${ano}-${mes}-${dia} ${hora}`;
    return format(new Date(data), formato);
  } catch (erro) {
    return '';
  }
}

