function getRouteAccessWeb(req: any) {

    let route = req.baseUrl.substr(config.middleurlWeb.length);

    /** mode original url */
    let action = {};
    switch (req.method) {
        case 'POST':
        action = { C: 1 };
        break;
        case 'GET':
        action = { R: 1 };
        break;
        case 'PUT':
        action = { U: 1 };
        break;
        case 'DELETE':
        action = { D: 1 };
        break;
        default:
        action = { [req.url.substr(1)]: 1 };
        break;
    }

    return { route, action };
}

