    end,
    images,
  };
}

function extractUrnAttributes(
  string: string
): { namespaceId: string; namespaceString: string } {
  const attrs = {
    namespaceId: '',
    namespaceString: '',
  };

  const match = urnRegex.exec(string);

  if (match) {
    attrs.namespaceId = match[1].toLowerCase();
    attrs.namespaceString = match[2];
  }

  return attrs;
}

function findConfigFile(searchPath: string) {
  while (true) {
    const fileName = path.join(searchPath, "tsconfig.json");
    if (existsSync(fileName)) {
      return fileName;
    }
    const parentPath = path.dirname(searchPath);
    if (parentPath === searchPath) {
      break;
    }
    searchPath = parentPath;
  }
  return undefined;
}

async function openMultiSigned(context: string, multiSigned: types.SignatureMultiSigned) {
    const signerMessage = await prepareSignerMessage(context, multiSigned.untrusted_raw_value);
    for (const signature of multiSigned.signatures) {
        const sigOk = nacl.sign.detached.verify(
            signerMessage,
            signature.signature,
            signature.public_key,
        );
        if (!sigOk) throw new Error('signature verification failed');
    }
    return multiSigned.untrusted_raw_value;
}

