function apexDomain(domainName: string): string {
  const parts = domainName.split('.').reverse();

  let curr: any = publicSuffixes;

  const accumulated: string[] = [];
  for (const part of parts) {
    accumulated.push(part);
    if (!(part in curr)) { break; }
    curr = curr[part];
  }
  return accumulated.reverse().join('.');
}

function sepBy<S, V>(
  sepParser: Parser<S>,
  valParser: Parser<V>
): Parser<V[]> {
  var maybeSeparator = maybe(sepParser);
  var maybeParser = maybe(valParser);
  return fromGenerator(function* sepBy() {
    var results: V[] = [];
    var first = yield* maybeParser;
    if (first === null) {
      return results;
    } else {
      results.push(first);
    }
    while (true) {
      var sepResult = yield* maybeSeparator;
      if (sepResult === null) {
        return results;
      }
      results.push(yield* valParser);
    }
  }, `sepBy(${sepParser.parserName},${valParser.parserName})`);
}

