function innerAnglesOfPolygon(contour: number[], width: number) {

        let angles: number[] = [];
        if (contour.length > 3) {


            for (let i: number = 0; i < contour.length; i++) {
                let prevIdx = i - 1;
                if (prevIdx < 0) prevIdx = contour.length - 1;
                let nextIdx = i + 1;
                if (nextIdx >= contour.length) nextIdx = 0;

                let xprev = contour[prevIdx] % width;
                let yprev = Math.floor(contour[prevIdx] / width);

                let xcur = contour[i] % width;
                let ycur = Math.floor(contour[i] / width);

                let xnext = contour[nextIdx] % width;
                let ynext = Math.floor(contour[nextIdx] / width);

                let v1x = xprev - xcur;
                let v1y = yprev - ycur;

                let v2x = xnext - xcur;
                let v2y = ynext - ycur;

                let dot = v1x * v2x + v1y * v2y;
                let lenv1 = Math.sqrt(v1x * v1x + v1y * v1y);
                let lenv2 = Math.sqrt(v2x * v2x + v2y * v2y);

                let cos = dot / (lenv1 * lenv2);
                angles.push(Math.round(Math.acos(cos) / Math.PI * 180));
                // cos ang = dot / len(v1) * len(v2)
            }
        }
        return angles;
    }

function transferToAccount(targetAccount: Uint8Array, amount: U512, id: Ref<u64> | null = null): TransferResult {
    let targetBytes = new Array<u8>(targetAccount.length);
    for (let i = 0; i < targetAccount.length; i++) {
        targetBytes[i] = targetAccount[i];
    }
    let amountBytes = amount.toBytes();

    let optId: Option;
    if (id !== null) {
        optId = new Option(arrayToTyped(toBytesU64(id.value)));
    }
    else {
        optId = new Option(null);
    }
    const idBytes = optId.toBytes();

    let resultPtr = new Uint32Array(1);

    let ret = externals.transfer_to_account(
        targetBytes.dataStart,
        targetBytes.length,
        amountBytes.dataStart,
        amountBytes.length,
        idBytes.dataStart,
        idBytes.length,
        resultPtr.dataStart,
    );

    const error = Error.fromResult(ret);
    if (error !== null) {
        return TransferResult.makeErr(error);
    }

    const transferredTo = makeTransferredTo(resultPtr[0]);
    if (transferredTo !== null) {
        return TransferResult.makeOk(transferredTo);
    }
    return TransferResult.makeErr(Error.fromErrorCode(ErrorCode.Transfer));
}

