function unaryOp(base: SVNumeric, uop: TEUopType, source?: ExpressionNode): ShValue {
        let resultType: SVNumericType;
        let result: number | boolean | ExpNum | ExpBool;

        switch (uop) {
            case TEUopType.Neg:
                resultType = base.type === SVType.Float ? SVType.Float : SVType.Int;
                if (isConstant(base)) {
                    result = -base.value;
                } else if (base.type === SVType.Bool) {
                    // already casted. does not happen.
                    return SVError.create('do bool2int cast before calling unaryOp Neg', source);
                } else {
                    // Int/Float
                    result = ExpNum.uop(NumUopType.Neg, base.value, source);
                }
                break;
            case TEUopType.Not:
                resultType = SVType.Bool;
                if (isConstant(base)) {
                    result = !base.value;
                } else if (base.type === SVType.Bool) {
                    result = ExpBool.not(base.value as ExpBool, source);
                } else {
                    return SVError.create('do bool2int cast before calling unaryOp Not', source);
                }
                break;
        }

        switch (resultType) {
            case SVType.Bool:
                return SVBool.create(result as boolean | ExpBool, source);
            case SVType.Int:
                return SVInt.create(result as number | ExpNum, source);
            case SVType.Float:
                return SVFloat.create(result as number | ExpNum, source);
        }
    }

async function withReleasers<T>(
  callback: (releasers: Releasers, release: Release) => Promise<T>
): Promise<T> {
  const releasers: Releasers = [];
  const release: Release = async () => {
    await Promise.all(releasers.map(fn => fn()));
  };
  try {
    return await callback(releasers, release);
  } catch (e) {
    try {
      await release();
    } catch (e2) {
      /* noop */
    }
    throw e;
  }
}

