function erode4Fast(grayscale: Uint8Array, width: number, height: number) {
        // 4x dilate 3x3 = 2x dilate 5x5 = 1x dilate 7x7
        //let xpass: Uint8ClampedArray = new Uint8ClampedArray(width * height);
        let xpass: Uint8Array = BufferManager.getInstance().getUInt8Buffer(width * height);

        let padding = 3;
        let idx = padding * width + padding;
        for (let y: number = padding; y < height - padding; y++) {

            let sum =
                grayscale[idx - 3 - 0] +
                grayscale[idx - 2 - 0] +
                grayscale[idx - 1 - 0] +
                grayscale[idx - 0 - 0] +
                grayscale[idx + 1 - 0] +
                grayscale[idx + 2 - 0] +
                grayscale[idx + 3 - 0];
            xpass[idx] = sum == 7 * 255 ? 255 : 0;

            idx++;

            for (let x: number = padding + 1; x < width - padding; x++) {
                // remove the element that falls out of the range
                sum -= grayscale[idx - 1 - 3 - 0];
                // and add the element that enters the range
                sum += grayscale[idx + 3 - 0];

                xpass[idx] = sum == 7 * 255 ? 255 : 0;
                idx++;
            }
            idx += 2 * padding;
        }

        let w3 = width + width + width;
        let w2 = width + width;


        //let dst2: Uint8Array = new Uint8Array(width * height);
        let dst2 = BufferManager.getInstance().getUInt8Buffer(width * height);

        idx = padding * width + padding;
        for (let x: number = padding; x < width - padding; x++) {
            idx = x + padding * width;

            let sum =
                xpass[idx - 0 - w3] +
                xpass[idx - 0 - w2] +
                xpass[idx - 0 - width] +
                xpass[idx - 0 - 0] +
                xpass[idx - 0 + width] +
                xpass[idx - 0 + w2] +
                xpass[idx - 0 + w3];
            dst2[idx] = sum == 7 * 255 ? 255 : 0;

            idx += width;

            for (let y: number = padding + 1; y < height - padding; y++) {

                sum -= xpass[idx - width - 0 - w3];
                sum += xpass[idx - 0 + w3];

                dst2[idx] = sum == 7 * 255 ? 255 : 0;

                idx += width;
            }
        }

        BufferManager.getInstance().releaseUInt8Buffer(xpass);

        return dst2;
    }

function findBonds(structure: Structure, props: InterBondComputationProps) {
    const builder = new InterUnitGraph.Builder<number, StructureElement.UnitIndex, InterUnitEdgeProps>();
    const hasIndexPairBonds = structure.models.some(m => IndexPairBonds.Provider.get(m));
    const hasExhaustiveStructConn = structure.models.some(m => StructConn.isExhaustive(m));

    if (props.noCompute || (structure.isCoarseGrained && !hasIndexPairBonds && !hasExhaustiveStructConn)) {
        return new InterUnitBonds(builder.getMap());
    }

    Structure.eachUnitPair(structure, (unitA: Unit, unitB: Unit) => {
        findPairBonds(unitA as Unit.Atomic, unitB as Unit.Atomic, props, builder);
    }, {
        maxRadius: props.maxRadius,
        validUnit: (unit: Unit) => props.validUnit(unit),
        validUnitPair: (unitA: Unit, unitB: Unit) => props.validUnitPair(structure, unitA, unitB)
    });

    return new InterUnitBonds(builder.getMap());
}

