function getLineMarkers(arg: string): number[] {
  if (arg[0] === "0" || arg[0] < "1") {
    console.log("Invalid line marker: cannot start with or be 0");
    Deno.exit(1);
  }
  if (!Number(arg.replace(":", ""))) {
    console.log("Invalid line marker: must be a number or number range");
    Deno.exit(1);
  }

  if (arg.includes(":")) {
    const markers = arg.split(":");
    let m1 = markers[0];
    let m2 = markers[1];

    if (m1 === "") m1 = "1";
    if (m2 === "") m2 = "-1";
    if (m1 > m2 && m2 !== "-1") {
      throw new Error("Invalid line marker: start cannot be greater than stop");
    }

    return [Number(m1) - 1, Number(m2)];
  } else if (!arg.includes(":")) {
    return [Number(arg[0]) - 1, Number(arg[0])];
  }

  console.log("Error getting line marker: " + arg);
  Deno.exit(1);
}

