function hsl(r:number, g:number, b:number):number[] {
        var max:number = Math.max(r, g, b),
            min:number = Math.min(r, g, b);

		/* tslint:disable:no-bitwise */
        var h:number,
            s:number,
            l:number = (max + min) >> 1;
		/* tslint:enable:no-bitwise */

        if (max === min) {
            h = s = 0;
        } else {
			var d:number = max - min;
			s = l > 127 ? d / (510 - max - min) : d / (max + min);

            switch (max) {
                case r:
                    h = (g - b) / d + (g < b ? 6 : 0);
                    break;
                case g:
                    h = (b - r) / d + 2;
                    break;
                case b:
                    h = (r - g) / d + 4;
                    break;
                default:
                    break;
            }

            h /= 6;
        }

        return [h * 255, s * 255, l];
    }

function convertLinks(doc: string, ns_name?: string): string {
    if (doc == undefined)
        return doc;

    if (ns_name == undefined)
        return doc;

    /**
     *  @example Captures #Clutter:optional-prop
     */
    const regex = new RegExp(`#${ns_name}[\\w\\d:-]*(?<!:)`, "gm");
    const result = regex.exec(doc);
    if (result != null) {
        for (const item of result) {
            // Just the namespace name, skip
            if (item == `#${ns_name}`) {
                continue;
            }

            let newItem = item;

            newItem = newItem.replace(`#${ns_name}`, "").replace(/:+/g, ".").replace(/-/g, "_");
            doc = doc.replace(item, `{@link ${newItem.toString()}}`);
        }
    }
    return doc;
}

