        const colors: number[] = [];
        for (let i = 0; i <= 0xF; ++i)
            colors[i] = 0;

        for (let x = 0; x < square; ++x) {
            for (let y = 0; y < square; ++y) {
                colors[im.getPixel(x0 + x, y0 + y)] += 1 
            }
        }

        let max = 1;
        for (let i = 1; i <= 0xF; ++i) {
            if (colors[i] >= colors[max]) {
                max = i;
            }
        }

        if (colors[max] == 0) {
            return 0;
        }

        return max;
    }

