function positionAtOffset(
    curve: any,
    length: number,
    offset: number,
    reverse: boolean
): THREE.CatmullRomCurve3 {
    let extrudePts = curve.points !== undefined ? curve.points : curve.getSpacedPoints(length);
    let splineTube = curve.computeFrenetFrames(length, false);

    let newPoints = [];
    let position2 = new THREE.Vector3();
    let normal = new THREE.Vector3();
    let binormal = new THREE.Vector3();
    for (let ii = 0; ii < extrudePts.length; ii++) {
        normal.copy(splineTube.normals[ii]).multiplyScalar(offset);
        binormal.copy(splineTube.binormals[ii]).multiplyScalar(0);
        position2.copy(extrudePts[ii]).add(normal).add(binormal);
        newPoints.push(position2.clone());
    }

    let curve3 = new THREE.CatmullRomCurve3(reverse ? newPoints.reverse() : newPoints);
    curve3.arcLengthDivisions = newPoints.length - 1;
    return curve3;
}

function replacePattern(inputLine: string, patternTag: string, replacementLines: string[], position?: number) : [string[], number] {
        let i = inputLine.lastIndexOf(patternTag, position);
        if (i < 0) {
            return [[inputLine], i];
        }

        let prefix = inputLine.substr(0, i);
        let suffix = inputLine.substr(i + patternTag.length);        

        // replacement is multiline
        if (replacementLines.length > 1) {
            let result: string[] = [];
            let replacementFirstLine = replacementLines[0];
            let replacementLastLine = replacementLines[replacementLines.length-1];
            result.push(prefix + replacementFirstLine);
            for (let index = 1; index < replacementLines.length-1; index++) {
                result.push(replacementLines[index]);
            }
            result.push(replacementLastLine + suffix);
            return [result, i];
        }

        // replacement is singleline
        let lineReplacement = "";

        if (replacementLines.length > 0) {
            // selection is not empty
            lineReplacement = replacementLines[0];
        }        
        return [[prefix +  lineReplacement + suffix], i];
    }

function getBootStrapComponent(tree: Tree, modulePath: string): {component: string, appId: string, filePath: string}[] {
    const moduleSource = getFileContent(tree, modulePath);
    let components: string[] = [];
    let toReturn: any[] = [];
    let decorator: ts.Node = getDecoratorSettings(tree, modulePath, 'NgModule');
    let bootstrapNode = getLiteral(decorator, 'bootstrap');

    if (!bootstrapNode) {
        throw new NgToolkitException(`Bootstrap not found in ${modulePath}.`, {fileContent: moduleSource});
    }

    bootstrapNode.forEachChild(node => {
        if (ts.isArrayLiteralExpression(node)) {
            node.elements.forEach((elem: ts.Identifier) => {
                components.push(elem.escapedText.toString());
            });
        }
    });

    let sourceFile: ts.SourceFile = ts.createSourceFile('temp.ts', moduleSource, ts.ScriptTarget.Latest);

    sourceFile.forEachChild(node => {
        if (ts.isImportDeclaration(node) && node.importClause && node.importClause.namedBindings) {
            let imports = moduleSource.substr(node.importClause.namedBindings.pos, node.importClause.namedBindings.end - node.importClause.namedBindings.pos);
            for (let component of components) {
                if (imports.indexOf(component) > -1 && ts.isStringLiteral(node.moduleSpecifier)) {
                    let componentPath = normalizePath(`${modulePath.substring(0, modulePath.lastIndexOf('/'))}/${node.moduleSpecifier.text}.ts`);
                    let componentDecorator: ts.Node = getDecoratorSettings(tree, componentPath, 'Component');
                    let appId;
                    componentDecorator.forEachChild(node => node.forEachChild(node =>  {
                        if (ts.isPropertyAssignment(node) && ts.isIdentifier(node.name) && node.name.escapedText === 'selector') {
                            appId = (node.initializer as ts.StringLiteral).text;
                        }
                    }));
                    let path = `${modulePath.substring(0, modulePath.lastIndexOf('/'))}/${node.moduleSpecifier.text}.ts`;
                    path = normalizePath(path);
                    toReturn.push({component: component, appId: appId, filePath: path})
                    break;
                }
            }
        }
    });

    return toReturn;
}

