function changeVectorTileBase(
    vector: ILayer,
    base: any,
    document: IDocument
) {
    const { layers } = document;
    if (!base) {
        return layers;
    }
    if (!layers) {
        return undefined;
    }
    const { id, source, sourceLayer, info } = base;

    layers.map((layer) => {
        if (layer.type === LayerType.GroupLayer) {
            if (layer.children) {
                if (id) {
                    loopGroupProp(vector.id, "id", base.id, layer);
                }
                if (source) {
                    loopGroupProp(vector.id, "source", base.source, layer);
                }
                if (sourceLayer) {
                    loopGroupProp(vector.id, "sourceLayer", base.sourceLayer, layer);
                }
                if (info) {
                    loopGroupProp(vector.id, "info", base.info, layer);
                }
            }
        } else {
            if (layer.id === vector.id) {
                if (layer.type === LayerType.VectorTile) {
                    let vectorlayer = new BaseLayer();
                    vectorlayer = { ...layer, source: undefined, sourceLayer: undefined };
                    if (id) {
                        vectorlayer.id = base.id;
                    }
                    if (source) {
                        vectorlayer.source = base.source;
                    }
                    if (sourceLayer) {
                        vectorlayer.sourceLayer = base.sourceLayer;
                    }
                    if (info) {
                        vectorlayer.info = base.info;
                    }
                    return vector;
                }
            }
            return layer;
        }
    });

    return layers;
}

