function formatHistoryMessage(message: string, users: UsersProviderService): Observable<string> {
    const userName = (userId: string) => {
        const parts = userId.split(':');

        if (parts.length === 1) {
            return users.getUser(parts[0], null).pipe(map(u => u.displayName));
        } else if (parts[0] === 'subject') {
            return users.getUser(parts[1], null).pipe(map(u => u.displayName));
        } else {
            if (parts[1].endsWith('client')) {
                return of(parts[1]);
            } else {
                return of(`${parts[1]}-client`);
            }
        }
    };

    let foundUserId: string | null = null;

    message = message.replace(/{([^\s:]*):([^}]*)}/, (match: string, type: string, id: string) => {
        if (type === 'user') {
            foundUserId = id;
            return REPLACEMENT_TEMP;
        } else {
            return id;
        }
    });

    message = message.replace(/{([^}]*)}/g, (match: string, marker: string) => {
        return `<span class="marker-ref">${marker}</span>`;
    });

    if (foundUserId) {
        return userName(foundUserId).pipe(map(t => message.replace(REPLACEMENT_TEMP, `<span class="user-ref">${t}</span>`)));
    }

    return of(message);
}

async function createTemporaryWorkTree(
  repository: Repository,
  commit: string
): Promise<LinkedWorkTree> {
  const workTreePath = await FSE.mkdtemp(getTemporaryDirectoryPrefix())
  await git(
    ['worktree', 'add', '-f', workTreePath, commit],
    repository.path,
    'addWorkTree'
  )
  // Because Git doesn't give enough information from stdout for the previous
  // Git call, this function enumerates the available worktrees to find the
  // expected worktree

  const workTrees = await listWorkTrees(repository)

  const directoryName = Path.basename(workTreePath)
  const workTree = workTrees.find(t => Path.basename(t.path) === directoryName)

  // intentionally vague here to cover `undefined` and `null`
  if (!workTree) {
    throw new Error(
      `[addWorkTree] Unable to find created worktree "${directoryName}"`
    )
  }

  return workTree
}

