async function render(tokens: tree, raw: boolean = false): Promise<string> {
    let parsed: string = "";
    for (const element of tokens) {
      if (typeof element === "string") parsed += element;
      else {
        switch (element.type) {
          case "root":
            parsed += await render(element.children, raw);
            break;
          case "tag":
            if (raw) {
              parsed += `{{${render(element.children, raw)}}}`;
            } else {
              const value = await replace(await render(element.children, raw));
              if (value === undefined) {
                if (silentFailReference) {
                  parsed += `{{${await render(element.children, raw)}}}`;
                } else {
                  throw new Error(
                    `<render>: undefined data referenced "${await render(
                      element.children,
                      raw,
                    )}"`,
                  );
                }
              } else parsed += value;
            }
            break;
          case "comment":
            if (!stripComments) {
              parsed += `<!--${await render(element.children, true)}-->`;
            }
            break;
        }
      }
    }
    return parsed;
  }

function sepBy1<S, V>(
  sepParser: Parser<S>,
  valParser: Parser<V>
): Parser<V[]> {
  var maybeSeparator = maybe(sepParser);
  return fromGenerator(function* sepBy1() {
    var results: V[] = [];
    while (true) {
      results.push(yield* valParser);
      var sepResult = yield* maybeSeparator;
      if (sepResult === null) {
        return results;
      }
    }
  }, `sepBy1(${sepParser.parserName},${valParser.parserName})`);
}

