function binOpStrLiteral(
        left: string,
        right: string,
        bop: TEBopType,
        source?: ParseNode
    ): ShValue | undefined {
        switch (bop) {
            case TEBopType.Add:
                return SVString.create(left + right, source);
            case TEBopType.Lt:
                return SVBool.create(left < right, source);
            case TEBopType.Lte:
                return SVBool.create(left <= right, source);
            case TEBopType.Eq:
                return SVBool.create(left === right, source);
            case TEBopType.Neq:
                return SVBool.create(left !== right, source);
            case TEBopType.Is:
                return SVBool.create(left === right, source);
            case TEBopType.IsNot:
                return SVBool.create(left !== right, source);
            case TEBopType.In:
                return SVBool.create(right.search(left) !== -1, source);
            case TEBopType.NotIn:
                return SVBool.create(right.search(left) === -1, source);
            default:
                return;
        }
    }

