function debounce<F extends (...args: any[]) => void>(
  f: F,
  timeout: number,
  target?: any
): F {
  let timer: number | undefined = undefined;
  return function (this: any, ...args: any[]) {
    target = target || this;

    timer && clearTimeout(timer);
    timer = setTimeout(() => {
      f.apply(target, args);
    }, timeout) as any;
  } as F;
}

