function computeDuration({
    factor,
    attempts,
    jitter,
    min,
    max
}: {
    factor: number;
    attempts: number;
    jitter: number;
    min: number;
    max: number;
}) {
    let ms = min * Math.pow(factor, attempts);
    if (jitter) {
        const rand = Math.random();
        const deviation = Math.floor(rand * jitter * ms);
        ms = (Math.floor(rand * 10) & 1) == 0 ? ms - deviation : ms + deviation;
    }
    return Math.min(ms, max) | 0;
}

