function rob(nums: number[]): number {
  const n = nums.length
  if (n <= 1) {
    return nums[0] || 0
  }
  let dp_1 = nums[0]
  let dp_2 = Math.max(nums[0], nums[1])

  for (let i = 3; i <= n; i++) {
    const next = Math.max(dp_1 + nums[i - 1], dp_2)
    dp_1 = dp_2
    dp_2 = next
  }
  return dp_2
}

