function sortLinkedList(head: ListNode | null): ListNode | null {
  const arr: ListNode[] = [];
  let current: ListNode = head;

  while (current) {
    arr.push(current);
    current = current.next;
  }

  arr.sort((a, b) => a.val - b.val);

  for (let i = 0; i < arr.length - 1; i += 1) {
    arr[i].next = arr[i + 1];
  }

  arr[arr.length - 1].next = null;

  return arr[0];
}

