function getPageRect(node: unknown): PageRect {
    if (node instanceof HTMLElement) {
        const rect = node.getBoundingClientRect();
        return {
            x: window.pageXOffset + rect.left,
            y: window.pageYOffset + rect.top,
            w: rect.width,
            h: rect.height
