function createLogger(options = {}) {
    const loggerOptions = Object.assign({}, defaults, options);

    const {
        logger,
        stateTransformer,
        errorTransformer,
        predicate,
        logErrors,
        diffPredicate,
    } = loggerOptions;

    /* Return if 'console' object is not defined */
    if (typeof logger === 'undefined') {
        return () => next => action => next(action);
    }

    /* Detect if 'createLogger' was passed directly to 'applyMiddleware'. */
    if (options.hasOwnProperty('getState') && options.hasOwnProperty('dispatch')) {
        /* eslint-disable-next-line no-console */
        console.error(`[redux-logger] redux-logger not installed. Make sure to pass logger instance as middleware:
            // Logger with default options
            import { logger } from 'redux-logger'
            const store = createStore(
                reducer,
                applyMiddleware(logger)
            )
            // Or you can create your own logger with custom options http://bit.ly/redux-logger-options
            import createLogger from 'redux-logger'
            const logger = createLogger({
                // ...options
            });
            const store = createStore(
                reducer,
                applyMiddleware(logger)
            )
        `);

        return () => next => action => next(action);
    }

    const logBuffer: any = [];

    return ({ getState }) => next => (action) => {
        /* Exit early if predicate function returns 'false' */
        if (typeof predicate === 'function' && !predicate(getState, action)) {
            return next(action);
        }

        const logEntry: any = {};

        logBuffer.push(logEntry);

        logEntry.started = timer.now();
        logEntry.startedTime = new Date();
        logEntry.prevState = stateTransformer(getState());
        logEntry.action = action;

        let returnedValue;
        if (logErrors) {
            try {
                returnedValue = next(action);
            } catch (e) {
                logEntry.error = errorTransformer(e);
            }
        } else {
            returnedValue = next(action);
        }

        logEntry.took = timer.now() - logEntry.started;
        logEntry.nextState = stateTransformer(getState());

        const diff = loggerOptions.diff && typeof diffPredicate === 'function'
            ? diffPredicate(getState, action)
            : loggerOptions.diff;

        printBuffer(logBuffer, Object.assign({}, loggerOptions, { diff }));
        logBuffer.length = 0;

        if (logEntry.error) { throw logEntry.error; }
        return returnedValue;
    };
}

function oAuthComplete(params: { accept?: boolean } = {}) {
    return wrapInLoader(
        async (
            dispatch,
            getState,
        ): Promise<{
            success: boolean;
            redirectUri: string;
        }> => {
            const oauthData = getState().auth.oauth;

            if (!oauthData) {
                throw new Error('Can not complete oAuth. Oauth data does not exist');
            }

            try {
                const resp = await oauth.complete(oauthData, params);
                localStorage.removeItem('oauthData');

                if (resp.redirectUri.startsWith('static_page')) {
                    const displayCode = /static_page_with_code/.test(resp.redirectUri);

                    const [, code] = resp.redirectUri.match(/code=(.+)&/) || [];
                    [, resp.redirectUri] = resp.redirectUri.match(/^(.+)\?/) || [];

                    dispatch(
                        setOAuthCode({
                            success: resp.success,
                            code,
                            displayCode,
                        }),
                    );
                }

                return resp;
            } catch (error) {
                const resp:
                    | {
                          acceptRequired: boolean;
                      }
                    | {
                          unauthorized: boolean;
                      } = error;

                if ('acceptRequired' in resp) {
                    dispatch(requirePermissionsAccept());

                    return Promise.reject(resp);
                }

                return handleOauthParamsValidation(resp);
            }
        },
    );
}

