function normalizeRoadsData(points: any[]): Road[] {
  const byName: any = {};
  points.forEach((point: any) => {
    const roadName: string = point.name;
    const purePoint = {
      coord: point.coord,
      id: point.id,
      pics: point.pics
    };
    if (byName[roadName]) {
      byName[roadName].points.push(purePoint);
    } else {
      byName[roadName] = {
        id: roadName,
        name: roadName,
        points: [purePoint]
      };
    }
  });
  return Object.values(byName);
}

