  return (source: Observable<T>) => {
    return new Observable(sub => {
      source.subscribe({
        next: val => {
          sub.next(val);
          cdr.markForCheck();
        },
        error: error => {
          sub.error(error);
          cdr.markForCheck();
        },
        complete: () => sub.complete(),
      });
    });
  };
}

