          res.duration = VideoEl.duration;
          VideoEl.remove()
          typeof success === 'function' && success(res)
          typeof complete === 'function' && complete(res)
          taroChooseVideoCallback(res)
          taroChooseVideo!.value = ''
        }
      }
    }
