function CharactersReducer(state = defaultState, action: ReduxAction<any>) {
	switch (action.type) {
		case ActionType.ATTACK: {
			const character = action.payload.character;
			const attack = action.payload.action;
			const indexOfCharacter = state.indexOf(character)
			let newState = [...state];
			// Change stances if we need
			if (attack.toStance) {
				const newStance = character.stances.find((s: Stance) => s.name === attack.toStance)
				if (!newStance) {
					throw new Error('Stance not found: ' + attack.toStance + ' when performing attack: ' + attack.name)
				}
				newState = [
					...newState.slice(0, indexOfCharacter),
					new Character(character.name, character.stances, newStance, character.health, character.colors),
					...newState.slice(indexOfCharacter + 1)
				]
			}
			// Apply effects
			if (attack.effect) {
				switch (attack.effect) {
					case 'Battlecry': {
						// Put everyone into offensive stance
						newState = newState.map((c: Character) => {
							const newStance = c.stances.find((s: Stance) => s.name === "Offensive");
							if (!newStance) {
								throw new Error('Offensive stance not found while Battlecry')
							}
							return new Character(c.name, c.stances, newStance, c.health, c.colors)
						})
						break;
					}
					case 'Ice Barrier': {
						// Put everyone into defensive stance
						newState = newState.map((c: Character) => {
							const newStance = c.stances.find((s: Stance) => s.name === "Defensive");
							if (!newStance) {
								throw new Error('Defensive stance not found while Ice Barrier')
							}
							return new Character(c.name, c.stances, newStance, c.health, c.colors)
						})
						break;
					}
					case 'Heal': {
						// Heal 3 on every party member
						newState = newState.map((c: Character) => {
							return new Character(c.name, c.stances, c.currentStance, c.health + 2, c.colors)
						})

					}
				}
			}
			return newState
		}
		default:
			return state;
	}
}

function cloner<T>(
  objectToClone: T,
  allOptions: TNonOptionalCloneOptions,
  internalData: IClonerInternalData
): T {
  const { instancesToRefer, propsToRefer, valueFiltererToRefer, customCloners } = allOptions;
  const { clonedObjects, finalizers, parent, key } = internalData;

  // Pass primitives & functions
  if (objectToClone === null || !(objectToClone instanceof Object) || objectToClone instanceof Function) {
    return objectToClone;
  }

  // Pass unwanted references
  if (instancesToRefer.some(instance => objectToClone instanceof instance)) {
    return objectToClone;
  }

  // Pass filterer results
  if (valueFiltererToRefer(objectToClone)) {
    return objectToClone;
  }

  // If cloned before, skip circular cloning
  if (clonedObjects.has(objectToClone)) {
    if (clonedObjects.get(objectToClone) === CLONING_IN_PROGRESS) {
      finalizers.push(() => {
        parent[key] = clonedObjects.get(objectToClone);
      });
      return null;
    }
    return clonedObjects.get(objectToClone) as T;
  }

  // Mark object as cloning
  clonedObjects.set(objectToClone, CLONING_IN_PROGRESS);

  // Clone
  const customCloner = Array.from(customCloners.keys()).find(val => objectToClone instanceof val);
  const result = customCloners.get(customCloner)(objectToClone, allOptions, {...internalData});
  clonedObjects.set(objectToClone, result);
  return result;
}

