        outputChannel.appendLine(parameters.join(" "))
        const lpg_process = child_process.spawn(cmd_string, parameters, spawnOptions);

        const outputList: string[] = [];
        lpg_process.stderr.on("data", (data) => {
            let text = data.toString() as string;
            if (text.startsWith("Picked up _JAVA_OPTIONS:")) {
                const endOfInfo = text.indexOf("\n");
                if (endOfInfo === -1) {
                    text = "";
                } else {
                    text = text.substr(endOfInfo + 1, text.length);
                }
            }
            if (text.length > 0) {
                outputList.push(text);
            }
        });
        lpg_process.stdout.on("data",(data)=>{
            let text = data.toString() as string;
            outputList.push(text);
        })
        lpg_process.on("close", (code) => {
            resolve(outputList); // Treat this as non-grammar output (e.g. Java exception).
        });
    });
}

function collectUnusedSymbols(sourceFile: ts.SourceFile, typeChecker: ts.TypeChecker, unusedExports?: ExportData[]): string[] {
	const symbols = new Map<ts.Symbol, ts.Symbol[]>();
	const symKeys: ts.Symbol[] = [];
	const exportedSymKeys: ts.Symbol[] = [];

	function processNode(node: ts.Node) {
		const baseSym = typeChecker.getSymbolAtLocation(node);
		if (baseSym) {
			//const s = typeChecker.getAliasedSymbol(baseSym);
			const s = baseSym;
			if (isDeclarationSymbol(s, node)) {
				let parentSymbol: ts.Symbol | undefined;
				if (s.getFlags() === ts.SymbolFlags.Method ||
					s.getFlags() === ts.SymbolFlags.Property ||
					s.getFlags() === ts.SymbolFlags.NamespaceModule) {
					parentSymbol = findParentSymbol(symKeys, node);
				}
				if (!symbols.get(s)) {
					//console.log('Declaration symbol:', s.name);
					symbols.set(s, []);
					symKeys.push(s);
				}
				if (parentSymbol) {
					//console.log(`  (found parent symbol: ${parentSymbol.name})`);
					// 'parent (parentSymbol) is referring child (s)'
					const arr = symbols.get(s)!;
					arr.push(parentSymbol);
				}
			} else {
				//console.log('Reference symbol:', s.name);
				symKeys.forEach((x) => {
					if (isSymbolReferring(x, s, node, exportedSymKeys)) {
						//console.log(`  (found declaration: ${x.name})`);
						// 'x' is referring 's'
						const arr = symbols.get(s);
						if (arr) {
							arr.push(x);
						}
					}
				});
			}
		}
		node.forEachChild(processNode);
	}
	sourceFile.forEachChild(processNode);

	//console.log(`collectUnusedSymbols [file = ${sourceFile.fileName}]`);
	//console.log(`  unused exports:`);
	//unusedExports && unusedExports.forEach((exp) => exp.namedExports.forEach((x) => console.log(`    ${x.baseName || x.name} as ${x.name}`)));
	return reduceNoEntryMap(symbols, symKeys, (a, b) => a.name === b.name, (s) => {
		const usingExport = isUsingExportSymbol(sourceFile, s, unusedExports);
		if (!s.declarations) {
			return true;
		}
		//console.log(`  Symbol '${s.name}'[${s.flags}]: usingExport = `, usingExport);
		if (usingExport && exportedSymKeys.some((x) => x === s)) {
			return false;
		}
		const d = s.declarations[0];
		if (!d) {
			return true;
		}
		return !usingExport || !(
			ts.isExportDeclaration(d) ||
			ts.isExportAssignment(d) ||
			ts.isExportSpecifier(d) ||
			(d.modifiers && d.modifiers.some((m) => m.kind === ts.SyntaxKind.ExportKeyword))
		);
	}).map((sym) => {
		let name = sym.name;
		if (sym.declarations) {
			sym.declarations.forEach((d) => {
				mapEntityWithName((_n, exportName, baseName, i) => {
					if (i === 0) {
						name = baseName || exportName;
					}
				}, d, sourceFile);
			});
		}
		return name;
	});
}

async function replace(tag: string): Promise<string | undefined> {
    tag = tag.trim();
    const parts = tag.split(" "),
      key: string | undefined = parts.find((part) => !/(?<!\\):/.test(part)),
      modifiers: Record<string, string> = Object.fromEntries(
        parts
          .map((part) => part.split(/(?<!\\):/))
          .filter((part) => part.length > 1)
          .map((part) => [part[0], part.slice(1).join(":")]),
      );
    if (!key) return undefined;
    if (modifiers.if && !get(modifiers.if)) return "";
    let value = get(key);
    if (value === undefined) return value;
    if (Array.isArray(value)) value = value.join(modifiers.join ?? ", ");
    value = typeof value === "object"
      ? JSON.stringify(value, null, 2)
      : String(value);
    if (modifiers.for) {
      const looper = get(modifiers.for);
      if (!Array.isArray(looper)) return undefined;
      let result = "";
      for (const elem of looper) {
        const scoped = new Map(data);
        if (modifiers.as) {
          scoped.set(modifiers.as, elem);
        }
        result += await lib(
          { template: value as string, data: scoped },
          { stripComments, silentFailReference },
        );
      }
      return result;
    }
    return await lib(
      { template: value as string, data: data },
      { stripComments, silentFailReference },
    );
  }

function fileSize(bytes: number, si: boolean = true) {
  const thresh = si ? 1000 : 1024;
  if (Math.abs(bytes) < thresh) {
    return `${bytes}B`;
  }

  const units = si
    ? ["kB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]
    : ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];

  let unit = -1;
  let remainingBytes = bytes;
  do {
    remainingBytes /= thresh;
    unit += 1;
  } while (Math.abs(remainingBytes) >= thresh && unit < units.length - 1);

  return `${remainingBytes.toFixed(2)}${units[unit]}`;
}

