function findInFnDef(def: FnDefNode, outerRefsMap: OuterRefsMap): ReadonlyArray<UID> {
  if (def.body.kind === NK.Embed) {
    outerRefsMap.set(def, new Set());
    return [];
  }

  const locallyBound = new Set<UID>();
  for (const param of def.params) {
    const ident = (param.kind === NK.TypedPattern) ? param.pattern : param;
    locallyBound.add(ident.nid);
  }

  const subOrefs = findInValueExpr(def.body, outerRefsMap);

  const orefs = subOrefs.filter(ref => !locallyBound.has(ref));
  outerRefsMap.set(def, new Set(orefs));

  return orefs;
}

