  t0: number,
  tn: number,
  tw: number,
  divider: number,
  dx: number
): ItimelineOperationResult {
  const twPart = tw / divider;
  const dxPercent = dx / tw;

  return {
    t0: t0 + twPart * dxPercent,
    tn: tn - twPart * (1 - dxPercent)
  };
}

