function applyDefaultValues(
  requestParameters: Record<string, string | number | boolean> = {},
  expectedParameters: Record<string, OcParameter> = {}
): Record<string, string | number | boolean> {
  const optionalParametersWithDefaults = Object.entries(
    expectedParameters
  ).filter(
    (params): params is [string, OptionalParameterWithDefault] =>
      !params[1].mandatory && typeof params[1].default !== 'undefined'
  );

  optionalParametersWithDefaults.forEach(
    ([expectedParameterName, expectedParameter]) => {
      const param = requestParameters[expectedParameterName];
      if (param === null || param === undefined) {
        requestParameters[expectedParameterName] = expectedParameter.default;
      }
    }
  );

  return requestParameters;
}

function expandSymbol(sm: symbol): BelT {
  let s: string = nom(sm);

  if (s.indexOf("|") > -1) {
    const parts: string[] = s.split("|");
    return join(t, join(sym(parts[0]), join(sym(parts[1]), null)));
  }

  if (s.indexOf(".") > -1 || s.indexOf("!") > -1) {
    let upon: boolean = false;
    let bang: boolean = s[0] === "!";

    if (s[0] === "." || bang) {
      upon = true;
      s = s.substring(1);
    }

    const splitters = s.split("").filter(s => s === "." || s === "!");
    const parts: string[] = s.split(/[!\.]/);
    let result: Pair = null;

    for (let i: number = parts.length - 1; i >= 0; i--) {
      let psm: BelT = sym(parts[i]);

      if (i > 0 && splitters[i - 1] === "!") {
        psm = join(sym("quote"), join(psm, null));
      }

      result = join(psm, result);
    }

    if (upon) {
      if (bang) {
        result = join(sym("quote"), result);
        return join(sym("upon"), join(result, null));
      } else {
        return join(sym("upon"), result);
      }
    } else {
      return result;
    }
  }

  // (t x ((quote (compose (compose no f) g)) a))
  // (t x ((compose (compose no f) g) (quote a)))
  // (t x ((compose (compose no f) g) (quote a)))

  if (s.indexOf(":") > -1) {
    const parts: string[] = s.split(":");
    let result: Pair = null;

    for (let i: number = parts.length - 1; i >= 0; i--) {
      let psm: BelT = sym(parts[i]);
      result = join(psm, result);
    }

    return join(sym("compose"), result);
  }

  if (s[0] === "~") {
    return join(
      sym("compose"),
      join(sym("no"), join(sym(s.substring(1)), null))
    );
  }

  return sm;
}

function stubAsyncIterationCall<ResponseType>(
  responses?: ResponseType[],
  error?: Error
) {
  let counter = 0;
  const asyncIterable = {
    [Symbol.asyncIterator]() {
      return {
        async next() {
          if (error) {
            return Promise.reject(error);
          }
          if (counter >= responses!.length) {
            return Promise.resolve({done: true, value: undefined});
          }
          return Promise.resolve({done: false, value: responses![counter++]});
        },
      };
    },
  };
  return sinon.stub().returns(asyncIterable);
}

