function CalculateRotationAngle(gridCell: { x: number, y: number }, grid: { x0: number, y0: number, xStep: number, yStep: number }, sizeCoef: number, positionX: number, positionY: number): number {
                var angle = 0;

                var containerX = (gridCell.x + 0.5) * grid.xStep + grid.x0 + (sizeCoef - 1) * grid.xStep / 2;
                var containerY = (gridCell.y + 0.5) * grid.yStep + grid.y0 + (sizeCoef - 1) * grid.yStep / 2;

                var v = {
                    x: positionX - containerX,
                    y: positionY - containerY
                };
                var len = Math.sqrt(v.x * v.x + v.y * v.y);

                v.x = v.x / len;
                v.y = v.y / len;

                var acos = Math.acos(-v.y);

                angle = acos * v.x / Math.abs(v.x);

                angle = angle * 180 / Math.PI;
                if (angle < 0)
                    angle += 360;


                return angle;
            }

function createAndCompileModel(
  layers,
  hiddenSize,
  rnnType,
  digits,
  vocabularySize
) {
  const maxLen = digits + 1 + digits;

  const model = tf.sequential();
  switch (rnnType) {
    case 'SimpleRNN':
      model.add(
        tf.layers.simpleRNN({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          inputShape: [maxLen, vocabularySize],
        })
      );
      break;
    case 'GRU':
      model.add(
        tf.layers.gru({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          inputShape: [maxLen, vocabularySize],
        })
      );
      break;
    case 'LSTM':
      model.add(
        tf.layers.lstm({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          inputShape: [maxLen, vocabularySize],
        })
      );
      break;
    default:
      throw new Error(`Unsupported RNN type: '${rnnType}'`);
  }
  model.add(tf.layers.repeatVector({ n: digits + 1 }));
  switch (rnnType) {
    case 'SimpleRNN':
      model.add(
        tf.layers.simpleRNN({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          returnSequences: true,
        })
      );
      break;
    case 'GRU':
      model.add(
        tf.layers.gru({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          returnSequences: true,
        })
      );
      break;
    case 'LSTM':
      model.add(
        tf.layers.lstm({
          units: hiddenSize,
          recurrentInitializer: 'glorotNormal',
          returnSequences: true,
        })
      );
      break;
    default:
      throw new Error(`Unsupported RNN type: '${rnnType}'`);
  }
  model.add(
    tf.layers.timeDistributed({
      layer: tf.layers.dense({ units: vocabularySize }),
    })
  );
  model.add(tf.layers.activation({ activation: 'softmax' }));
  model.compile({
    loss: 'categoricalCrossentropy',
    optimizer: 'adam',
    metrics: ['accuracy'],
  });
  return model;
}

