function concatenate(...arrays: (ArrayBuffer | Uint8Array)[]): ArrayBuffer {
    const buffersLengths = arrays.map((array) => array.byteLength)
    const totalLength = buffersLengths.reduce((p, c) => p + c, 0)
    const buffer = new Uint8Array(totalLength)
    buffersLengths.reduce(function (p, c, i) {
        const v = arrays[i]
        if (v instanceof ArrayBuffer) {
            buffer.set(new Uint8Array(v), p)
        } else {
            buffer.set(v, p)
        }
        return p + c
    }, 0)
    return buffer.buffer
}

function applyMiddleware(...middlewares: Middleware[]): StoreEnhancer<any> {
  return (createStore: StoreEnhancerStoreCreator) =>
    <S, A extends AnyAction>(reducer: Reducer<S, A>, preloadedState?: PreloadedState<S>) => {
      const store = createStore(reducer, preloadedState)
      let dispatch: Dispatch = () => {
        throw new Error(
          'Dispatching while constructing your middleware is not allowed. ' +
            'Other middleware would not be applied to this dispatch.'
        )
      }

      const middlewareAPI: MiddlewareAPI = {
        getState: store.getState,
        dispatch: (action, ...args) => dispatch(action, ...args),
      }
      const chain = middlewares.map((middleware) => middleware(middlewareAPI))
      dispatch = compose<typeof dispatch>(...chain)(store.dispatch)

      return {
        ...store,
        dispatch,
      }
    }
}

