            var count:number = used[i][0];
            var p:number = used[i][1];

			/* tslint:disable:no-bitwise */
            var c:number[] = [~~(samples[p] / count), ~~(samples[p + 1] / count), ~~(samples[p + 2] / count), count];
			/* tslint:enable:no-bitwise */

            stats.push(c);
            pixels += count;
        }

        for (i = 0; i < stats.length; i++) {
            stats[i][3] /= pixels;
        }

