function deepTree(list: MenuProps[]): MenuProps[] {


    let newList: MenuProps[] = [];
    let map: any = {};

    list.forEach(e => {
        if (e.id) {
            return map[e.id] = e
        }
    });

    list.forEach(e => {
        let parent
        if (e.parentId) {
            parent = map[e.parentId];
        }

        if (parent) {
            (parent.children || (parent.children = [])).push(e);
        } else {
            if (!e.parentId) {
                newList.push(e);
            }
        }
    });


    const fn = (list: MenuProps[]) => {
        list.map(e => {
            if (e.children instanceof Array) {
                e.children = orderBy(e.children, 'sort');

                if (e.children) {
                    fn(e.children);
                }
            }
        });
    };

    let arr = newList.filter(e => e.id == null)

    newList.map(e => {
        if (e.id != null && arr.length !== 0) {
            arr[0].children?.push(e)
        }
    })

    if (arr.length === 0) {
        fn(newList);
        return orderBy(newList, 'orderNum');
    } else {
        fn(arr);
        return orderBy(arr, 'orderNum');
    }

}

