function queueFromEndpoint(endpoint: backend.Endpoint & backend.TaskQueueTriggered): Queue {
  const queue: Required<Queue> = {
    ...(JSON.parse(JSON.stringify(DEFAULT_SETTINGS)) as Omit<Required<Queue>, "name">),
    name: queueNameForEndpoint(endpoint),
  };
  if (endpoint.taskQueueTrigger.rateLimits) {
    proto.copyIfPresent(
      queue.rateLimits,
      endpoint.taskQueueTrigger.rateLimits,
      "maxConcurrentDispatches",
      "maxDispatchesPerSecond"
    );
  }
  if (endpoint.taskQueueTrigger.retryConfig) {
    proto.copyIfPresent(
      queue.retryConfig,
      endpoint.taskQueueTrigger.retryConfig,
      "maxAttempts",
      "maxDoublings"
    );
    proto.convertIfPresent(
      queue.retryConfig,
      endpoint.taskQueueTrigger.retryConfig,
      "maxRetryDuration",
      "maxRetrySeconds",
      nullsafeVisitor(proto.durationFromSeconds)
    );
    proto.convertIfPresent(
      queue.retryConfig,
      endpoint.taskQueueTrigger.retryConfig,
      "maxBackoff",
      "maxBackoffSeconds",
      nullsafeVisitor(proto.durationFromSeconds)
    );
    proto.convertIfPresent(
      queue.retryConfig,
      endpoint.taskQueueTrigger.retryConfig,
      "minBackoff",
      "minBackoffSeconds",
      nullsafeVisitor(proto.durationFromSeconds)
    );
  }
  return queue;
}

