function insertBefore(previousLines: string, lineFrom1: number, newLine: string): string {
    const lines = previousLines.split("\n");
    if (lines.length < lineFrom1) {
        return `## oops, there are only ${lines.length} lines. Unable to insert before line ${lineFrom1}`;
    }
    const before = lines.slice(0, lineFrom1 - 1);
    const after = lines.slice(lineFrom1 - 1);
    return before.concat([newLine]).concat(after).join("\n");
}

async function driveListFiles(drive: drive_v3.Drive, searchQuery: string, pageSize?: number): Promise<drive_v3.Schema$File[]> {
  return new Promise<any[]>((resolve, reject) => {
    const qs = {
      includeItemsFromAllDrives: true,
      supportsAllDrives: true,
      q: searchQuery,
      orderBy: 'modifiedTime desc',
      fields: 'files(id, name, mimeType, size)',
      pageSize: pageSize || 20,
      corpora: 'allDrives'
    };

    drive.files.list(
      qs
      , function (err: Error, res: any) {
        if (err) {
          reject(err);
        }
        if (!res || !res.data || !res.data.files) {
          return reject('No data found');
        }
        resolve(res.data.files);
      });
  });
}

function useSvgScroll({ elemRef }: { elemRef: RefObject<SVGGElement> }) {
  const [scrollX, setScrollX] = useState(10)
  const prevTouchXRef = useRef(0)
  const maxScrollRef = useRef(0)

  useEffect(() => {
    if (!elemRef.current) {
      return () => {}
    }

    const elem = elemRef.current
    maxScrollRef.current =
      elem.getBoundingClientRect().width - window.innerWidth + 10

    function onTouchMove(e: TouchEvent) {
      const currentX = e.touches[0].clientX

      const scrollDist = prevTouchXRef.current
        ? Math.abs(currentX - prevTouchXRef.current)
        : 0

      setScrollX((scroll) =>
        clamp(
          currentX > prevTouchXRef.current
            ? scroll + scrollDist
            : scroll - scrollDist,
          -maxScrollRef.current,
          10
        )
      )

      prevTouchXRef.current = currentX
    }

    function onTouchEnd() {
      prevTouchXRef.current = 0
    }

    elem.addEventListener('touchmove', onTouchMove)
    elem.addEventListener('touchend', onTouchEnd)

    return () => {
      elem.removeEventListener('touchmove', onTouchMove)
      elem.removeEventListener('touchend', onTouchEnd)
      prevTouchXRef.current = 0
    }
  }, [elemRef, setScrollX])

  return { scrollX }
}

