        }
        return dst;
    }

function split(
    string: string,
    separator: string,
    openBrace: string,
    closeBrace: string
): string[] {
    const result: string[] = [];

    let current = "";
    let index = 0;
    let depth = 0;

    while (index < string.length) {
        if (depth === 0 && string.startsWith(separator, index)) {
            result.push(current);

            current = "";

            index += separator.length;
        } else {
            let addStr = "";

            if (string.startsWith(openBrace, index)) {
                depth++;

                addStr = openBrace;
            } else if (string.startsWith(closeBrace, index)) {
                depth--;

                if (depth < 0) {
                    throw new Error(`Mismatched braces in string "${string}"`);
                }

                addStr = closeBrace;
            } else {
                addStr = string.slice(index, index + 1);
            }

            current += addStr;
            index += addStr.length;
        }
    }

    if (depth !== 0) {
        throw new Error(`Mismatched braces in string "${string}"`);
    }

    result.push(current);

    return result;
}

