async function consoleRiskInterceptor(response) {
  const { data: responseData } = response
  const { config: { risk } } = response
  if (!risk) return response
  const { code } = risk
  switch (responseData.code) {
  case code.doubleConfirm:
    try {
      const newResponse = await handleDoubleConfirm(response)
      return newResponse
    } catch (e) {
      console.error('[handleDoubleConfirm] failed: ', e.message)
      return response
    }
  case code.forbidden:
    return response
  default:
    return response
  }
}

function getMethodSignature(tree: Tree, filePath: string, name: string): string | null {
    let fileContent = getFileContent(tree, filePath);
    let results: any = fileContent.match(new RegExp("(?:public|private|).*"+ name +".*?\\(([\\s\\S]*?\\))"));
    if (results) {
        fileContent = fileContent.substr(results.index);
        let lines = fileContent.split('\n');
        let endCut = 0;
        let openingBraces = 0;
        for (let line of lines) {
                endCut += line.length + 1

            openingBraces += (line.match(/{/g) || []).length;
            if (openingBraces > 0) {
                break;
            }
        }

        return fileContent.substr(0, endCut);
    } else {
        return null;
    }
}

