function partialProxy(module: string, overrides: Object = {}) {

    const __module__    = module;
    const __overrides__ = JSON.stringify(overrides, (key, value) => {
        return typeof value === "function" ? value.toString() : value;
    });

    const interpolate = {
        __module__,
        __overrides__
    };

    const fn = () => {
        const module            = require("__module__");
        const overrideFunctions = __overrides__;
        const overrideKeys      = Object.keys(overrideFunctions);

        return new Proxy(module, {
            get: function (target, name: string, receiver) {

                const indexOfOverride = overrideKeys.indexOf(name);

                if (indexOfOverride === -1) {
                    return target[name];
                }

                const overrideKey = overrideKeys[indexOfOverride];

                return new Proxy(target[name], {
                    apply: function (target, context, args) {
                        return eval(`(${overrideFunctions[overrideKey]})`)(target, context, args);
                    }
                });

            }
        });
    };

    let stringified = fn.toString();
    for (const arg in interpolate) {
        stringified = stringified.replace(new RegExp(arg, "g"), interpolate[arg]);
    }

    return `(${stringified})()`;

}

function until(conditionFunction, labelOfWaitingCondition, waitMsTimeBeforeReject) {

    let now = new Date();//.toJSON().replace(/-/g, '_');

    if (!waitMsTimeBeforeReject) {
        waitMsTimeBeforeReject = 1000 * 5; // wait 5 seconds
    }

    let end = new Date(now.getTime() + waitMsTimeBeforeReject);
    const poll = (resolve, reject) => {
        if (conditionFunction()) {
            resolve();
        } else  {
            if (new Date() > end ) {
                labelOfWaitingCondition  = labelOfWaitingCondition ? labelOfWaitingCondition : "";
                reject(new Error('ErrorManager the condition \'' + labelOfWaitingCondition + '\' failed'));
                //throw new ErrorManager('ErrorManager the condition ' + labelOfWaitingCondition ? labelOfWaitingCondition : "" + ' failed');
                return;
            }
            setTimeout(_ => poll(resolve, reject), 400);
        }
    };

    return new Promise(poll);
}

