function sqrt(x: number): Multi<number> {
    if (x < 0) {
        return new Multi<number>();
    }
    if (x === 0) {
        return new Multi<number>(0);
    }
    const root_x = Math.sqrt(x);
    return new Multi<number>(-root_x, root_x);
}

