function feedFilter<Key = any, Value = any>(
  predicate: FilterFunction$<Value> | FilterFunction<Value>
): ReturnType<Key, Value> {
  const predicate$: FilterFunction$<Value> =
    typeof predicate === "function" ? of(predicate) : predicate;
  return (feed: ChangeFeed$<Key, Value>) => {
    return new Observable<ChangeFeed<Key, Value>>(subscriber => {
      const excluded = new Map<Key, Value>();
      const included = new Map<Key, Value>();
      let predicate: FilterFunction<Value> = _val => false;

      const predicateSub = predicate$.subscribe({
        next(newPredicate) {
          predicate = newPredicate;

          const toBeExcluded = Array.from(included.entries()).filter(
            ([, value]) => !predicate(value)
          );

          const toBeIncluded = Array.from(excluded.entries()).filter(
            ([, value]) => predicate(value)
          );

          for (const [key, value] of toBeExcluded) {
            excluded.set(key, value);
            included.delete(key);
            subscriber.next(["del", key]);
          }

          for (const [key, value] of toBeIncluded) {
            included.set(key, value);
            excluded.delete(key);
            subscriber.next(["set", key, value]);
          }
        },
        error(e) {
          console.error(e);
        }
      });

      const feedSub = feed.subscribe({
        next: changeFeedHandler<Key, Value>({
          initializing() {
            included.clear();
            excluded.clear();
            subscriber.next(["initializing"]);
          },
          ready() {
            subscriber.next(["ready"]);
          },
          set(key: Key, value: Value) {
            if (predicate(value)) {
              included.set(key, value);
              if (excluded.has(key)) {
                excluded.delete(key);
              }
              subscriber.next(["set", key, value]);
            } else {
              excluded.set(key, value);
              if (included.has(key)) {
                included.delete(key);
                subscriber.next(["del", key]);
              }
            }
          },
          del(key: Key) {
            if (excluded.has(key)) {
              excluded.delete(key);
            }
            if (included.has(key)) {
              included.delete(key);
              subscriber.next(["del", key]);
            }
          }
        }),
        complete() {
          subscriber.complete();
          predicateSub.unsubscribe();
        },
        error(error) {
          subscriber.error(error);
        }
      });

      return () => {
        predicateSub.unsubscribe();
        feedSub.unsubscribe();
      };
    });
  };
}

function filterOrganisations(orgs: any, searchFilter: string): any[] {
  const TEXT_FIELDS_TO_CHECK = ['name', 'postCode', 'sraId', 'admin'];
  if (!orgs) {
    return [];
  }
  if (!searchFilter || searchFilter === '') {
    return orgs;
  }
  searchFilter = searchFilter.toLowerCase();
  return orgs.filter((org: any) => {
    if (org) {
      for (const field of TEXT_FIELDS_TO_CHECK) {
        if (field === 'postCode' && postCodeMatches(org, searchFilter)) {
          return true;
        } else if (textFieldMatches(org, field, searchFilter)) {
          return true;
        }
      }
      if (org.pbaNumber) {
        for (const pbaNumber of org.pbaNumber) {
          if (pbaNumber.toLowerCase().includes(searchFilter)) {
            return true;
          }
        }
      }
      if (org.dxNumber && org.dxNumber.length > 0) {
        const dxNumber = org.dxNumber[0];
        if (dxNumber) {
          const matchesDxNumber = dxNumber.dxNumber && dxNumber.dxNumber.toLowerCase().includes(searchFilter);
          const matchesDxExchange = dxNumber.dxExchange && dxNumber.dxExchange.toLowerCase().includes(searchFilter);
          return matchesDxNumber || matchesDxExchange;
        }
      }
    }
    return false;
  });
}

