function areaOfTriangle([pointA, pointB, pointC]: Rectangle): number {
  const [ax, ay] = pointA;
  const [bx, by] = pointB;
  const [cx, cy] = pointC;

  const numerator = ax * (by - cy) + bx * (cy - ay) + cx * (ay - by);
  return abs(numerator / 2);
}

