function inverse(A: Mat) {
  let [det, AA, AAA, trA, trAA, trAAA] = matInfo(A);
  let total = sumScale(
    (trA * trA * trA - 3 * trA * trAA + 2 * trAAA) / 6, identity,
    - (trA * trA - trAA) / 2, A,
    trA, AA,
    -1, AAA
  );
  return scale(total, 1 / det);
}

