function checkHMACAuth(event: HttpEvent): boolean {
    const authHeader = parseAuthHeader(event);
    if (!authHeader) {
        return false;
    }
    const { signature } = authHeader;
    const expectedSignature = hmacSignature(event);
    if (signature !== expectedSignature) {
        console.error(`HMAC signature did not match expected: ${signature}`);
        return false;
    }
    return true;
}

function uploadImageAsPromise(image: Image, path: string) {
  const imageId = createUniqueId();

  const fileArray = image.uri.split('/');
  const fileName = fileArray[fileArray.length - 1];
  const ref = `${path}/${imageId}_${fileName}`;
  const storageRef = firebase.storage().ref(ref);

  const metadata = {
    contentType: 'image/jpeg'
  };

  const { base64 } = image;
  return storageRef
    .putString(base64, 'base64', metadata)
    .then(snapshot => {
      return snapshot.ref
        .getDownloadURL()
        .then(downloadURL => {
          return { id: imageId, url: downloadURL, ref };
        })
        .catch(error => {
          console.log(error);
          return false;
        });
    })
    .catch(error => {
      console.log(error);
      return false;
    });
}

