function compareDate(
  ...args: [Date, DateCompareOperator, Date] | [Date, Date]
): boolean | number {
  // Get dates and optional operator
  const [a, b] = args.length === 3 ? [args[0], args[2]] : [args[0], args[1]];
  const op = args.length === 3 ? args[1] : undefined;

  // Serialize dates for easy comparison
  const _a = DateSerializer.serializeDate(a);
  const _b = DateSerializer.serializeDate(b);

  // If no operator given, return number which has sign corresponding to the
  // difference of those dates.
  if (!op) {
    return _a - _b;
  }

  // Else return boolean corresponding to result of comparison by operator.
  switch (op) {
    case "<":
      return _a < _b;
    case "<=":
      return _a <= _b;
    case "==":
      return _a === _b;
    case ">=":
      return _a >= _b;
    case ">":
      return _a > _b;
  }
}

function getMethodBody(tree: Tree, filePath:string, name: string): string | null {
    let fileContent = getFileContent(tree, filePath);
    let results: any = fileContent.match(new RegExp("(?:public|private|).*" + name + ".*?\\(((\\s.*?)*)\\).*\\s*{"));
    if (results) {
        fileContent = fileContent.substr(results.index);
        let lines = fileContent.split('\n');

        let startCut = 0;
        let methodLength = 0;
        let openingBraces = 0;
        let closingBraces = 0;
        let openBraces = 0;
        for (let line of lines) {
            if (openBraces == 0) {
                startCut += line.length + 1
            } else {
                methodLength += line.length + 1;
            }

            openingBraces += (line.match(/{/g) || []).length;
            closingBraces += (line.match(/}/g) || []).length;
            openBraces = openingBraces - closingBraces;

            if (openBraces == 0 && openingBraces > 0) {
                break;
            }
        }
        let methodContent = fileContent.substr(startCut, methodLength - 2);

        return methodContent;
    } else {
        return null;
    }
}

