function evolve(input: Structure): Structure {
  return input.map((line, y) => (
    line.map((location, x) => {
      switch (location) {
        case "L":
          if (countAdjacent(input, y, x, "#") === 0) {
            return "#";
          }
        case "#":
          if (countAdjacent(input, y, x, "#") >= 4) {
            return "L";
          }
      }
      return location
    })
  ))
}

function retrieveExampleClassNames(fileName: string, content: string): string[] {
  const sourceFile = ts.createSourceFile(fileName, content, ts.ScriptTarget.Latest, false);
  const componentClassNames: string[] = [];
  // tslint:disable-next-line:no-any
  const visitNode = (node: any): void => {
    if (node.kind === ts.SyntaxKind.ClassDeclaration) {
      if (node.decorators && node.decorators.length) {
        for (const decorator of node.decorators) {
          if (decorator.expression.expression.text === 'Component') {
            componentClassNames.push(node.name.text);
          }
        }
      }
    }

    ts.forEachChild(node, visitNode);
  };

  visitNode(sourceFile);
  return componentClassNames;
}

function processFolder(folder: string, req: Request, res: Response) {
    const url = `${protocol}://${hostname}:${port}${context}/api/files${
      folder.startsWith('user') ? '/' : '/user/'
    }${folder}`;
    const headers = { 'X-Session-Token': req?.cookies['BioStudiesToken'] || '' };

    return new Promise((resolve: any) => {
      needle('get', url, { headers: headers })
        .then((response: any) => {
          const folders: string[] = [];
          if (response.statusCode != 200) {
            res.sendStatus(response.status);
            resolve();
            return;
          }
          response.body.forEach((node: any) => {
            if (node.type === 'FILE') {
              res.write(`${node.path.startsWith('user/') ? node.path.substr(5) : node.path}/${node.name}\n`);
            } else {
              folders.push(`${node.path}/${node.name}`);
            }
          });
          Promise.all(folders.sort().map((folder) => processFolder(folder, req, res))).then(() => resolve());
        })
        .catch(function (err: any) {
          res.sendStatus(err?.status || 500);
          resolve();
          return;
        });
    });
  }

