function binOpStr(
        ctrSet: ConstraintSet,
        left: SVString,
        right: SVString,
        bop: TEBopType,
        source?: ExpressionNode
    ): ShValue | undefined {
        if (typeof left.value === 'string' && typeof right.value === 'string') {
            return binOpStrLiteral(left.value, right.value, bop, source);
        }

        const leftExp = typeof left.value === 'string' ? ExpString.fromConst(left.value) : left.value;
        const rightExp = typeof right.value === 'string' ? ExpString.fromConst(right.value) : right.value;
        let symName: string | undefined;

        switch (bop) {
            case TEBopType.Add:
                return SVString.create(ExpString.concat(leftExp, rightExp, source), source);
            case TEBopType.Eq:
            case TEBopType.Is:
                return SVBool.create(ExpBool.eq(leftExp, rightExp, source), source);
            case TEBopType.Neq:
            case TEBopType.IsNot:
                return SVBool.create(ExpBool.neq(leftExp, rightExp, source), source);
            case TEBopType.Lt:
                symName = 'bop_lt';
                break;
            case TEBopType.Lte:
                symName = 'bop_lte';
                break;
            case TEBopType.In:
                symName = 'bop_lt';
                break;
            case TEBopType.NotIn:
                symName = 'bop_lt';
                break;
            default:
                return;
        }

        // not implementable in our resolver.
        if (symName) return SVBool.create(ExpBool.fromSymbol(ctrSet.genSymBool(symName, source)), source);

        return;
    }

function orderByFilter(originalArray, filterFct, flag, sortFct) {
    let o = []

    let objectsCompared = [];

    if (!originalArray) {
        return [];
    }

    originalArray.forEach((objectOriginal, index) => {
        let tabOfArgForApply = []
        tabOfArgForApply.push(objectOriginal);
        let objectComparing = {
            keyToCompare: null,
            objectOriginal: null
        } ;
        objectComparing.keyToCompare = filterFct.apply(null, tabOfArgForApply);
        objectComparing.objectOriginal = objectOriginal;
        objectsCompared.push(objectComparing);
        //that.waitingBotConversations.splice(index, 1);
    });

    function compWithkeyToCompare (objectComparingA, objectComparingB?) {
        return sortFct(objectComparingA.keyToCompare, objectComparingB.keyToCompare) ;
    }

    o = objectsCompared.sort(compWithkeyToCompare);
//        o = objs.sort(sortFct);

    let tabOrdered = [];

    o.forEach((objectCompared, index) => {
        tabOrdered.push(objectCompared.objectOriginal) ;
    })

    if (flag) {
        tabOrdered.reverse();
    } else {
        return tabOrdered;
    }
}

