function getWindowBounds(current: number, last: number): [number, number] {
  const windowBuffer = 3;
  const safeCurrent = Math.min(Math.max(current, first), last);
  const windowFirst = safeCurrent - windowBuffer;
  const windowLast = safeCurrent + windowBuffer;
  if (windowFirst <= first) {
    return [
      first,
      // Plus one to take the place of front ellipsis.
      Math.min(windowLast + (first - windowFirst) + 1, last),
    ];
  }
  if (windowLast >= last) {
    return [
      // Minus one to take the place of back ellipsis.
      Math.max(windowFirst - (windowLast - last) - 1, first),
      last,
    ];
  }
  return [windowFirst, windowLast];
}

function isUsingExportSymbol(source: ts.SourceFile, sym: ts.Symbol, unusedExports: ExportData[] | undefined): boolean {
	if (!unusedExports) {
		return true;
	}
	let symName = sym.name;
	// sym.name may be 'default', so get original entity name
	if (sym.declarations) {
		sym.declarations.forEach((d) => {
			mapEntityWithName((_n, exportName, baseName, i) => {
				if (i === 0) {
					symName = baseName || exportName;
				}
			}, d, source);
		});
	}
	return !unusedExports.some((exp) => {
		return exp.namedExports.some((x) => {
			return (x.baseName || x.name) === symName;
		});
	});
}

