{
	const old = descriptor.value;
	// @ts-ignore
	descriptor.value = function (this: StringSourceMap, ...argv)
	{
		if (this.locked)
		{
			throw new ReferenceError(`locked`)
		}

		return old.apply(this, argv);
	};

	return descriptor
}

