function mapCloner(objectToClone: Map<any, any>, options: TNonOptionalCloneOptions, internalData) {
  const newMap = new Map();

  intersection(options.propsToRefer, Array.from(objectToClone.keys())).forEach(key => {
    newMap.set(key, objectToClone.get(key));
  });

  difference(Array.from(objectToClone.keys()), options.propsToRefer).forEach(key => {
    newMap.set(key, cloner(objectToClone.get(key), options, {...internalData, key, parent: newMap}));
  });

  return newMap;
}

function find_block(cm: any, lineno: number): Block {
		if (!lineno && lineno !== 0) lineno = cm.lastLine();

		let start = -1;
		// A line is in a block if it is wrapped in a ```math and ```
		// We start at lineno - 1 to ensure that event the trailing
		// ``` will be treated as part of a block
		for (let i = lineno; i >= cm.firstLine(); i--) {
			const line = cm.getLine(i);

			// If we encounter an end of block marker
			// then we know we wer not in a block
			if (line === '```') {
				return null;
			}
			else if (line === '```math') {
				start = i + 1;
				break;
			}
		}

		if (start === -1) return null;

		for (let i = start; i < cm.lineCount(); i++) {
			const line = cm.getLine(i);

			if (line.indexOf('```') === 0) {
				if (line.trim() === '```') {
					return { start: start, end: i - 1 };
				}

				return null;
			}
		}

		return null;
	}

