function normalizeOutputOptions(
	inputOptions: GenericConfigObject,
	rawOutputOptions: GenericConfigObject
): OutputOptions {
	if (!rawOutputOptions) {
		throw new Error('You must supply an options object');
	}
	// since deprecateOptions, adds the output properties
	// to `inputOptions` so adding that lastly
	const consolidatedOutputOptions = {
		output: { ...rawOutputOptions, ...rawOutputOptions.output, ...inputOptions.output }
	};
	const mergedOptions = mergeOptions({
		// just for backward compatiblity to fallback on root
		// if the option isn't present in `output`
		config: consolidatedOutputOptions,
		deprecateConfig: { output: true }
	});

	if (mergedOptions.optionError) throw new Error(mergedOptions.optionError);

	// now outputOptions is an array, but rollup.rollup API doesn't support arrays
	const outputOptions = mergedOptions.outputOptions[0];
	const deprecations = mergedOptions.deprecations;

	if (deprecations.length) addDeprecations(deprecations, inputOptions.onwarn);
	checkOutputOptions(outputOptions);

	return outputOptions;
}

async function parseHeaders(
  type: string,
  reader: Deno.Reader,
): Promise<HTTPPayloadInfo> {
  const parser = new HTTPParser(type);
  let headersObj: Headers | undefined;
  let infoResult: any;
  // @ts-ignore
  parser[HTTPParser.kOnHeadersComplete] = (info: any) => {
    headersObj = new Headers();
    let k: string = "";
    info.headers.forEach((element: string, i: number) => {
      if (i % 2 === 0) k = element;
      else headersObj?.set(k, element);
    });
    infoResult = info;

    // return 2 to skip processing body?
    return false;
  };
  // @ts-ignore
  parser[HTTPParser.kOnBody] = (args: any) => {
    // console.log("on body:", args);
    console.log("on body:", new TextDecoder().decode(args));
  };

  // @ts-ignore
  parser[HTTPParser.kOnMessageComplete] = () => {
    // console.log("!! request finished !!")
  };
  let len: number | null = -1;
  const buffer = new Uint8Array(1024);
  return new Promise(async (resolve) => {
    while (len !== null && !headersObj) {
      len = await reader.read(buffer);
      if (len) parser.execute(buffer, 0, len);
    }
    parser.finish();
    if (!headersObj) throw new Error(`Invalid http payload, no headers found`);
    const result = Object.assign(infoResult, {
      headersObj,
    });
    resolve(result);
  });
}

