function firstUniqChar(s: string): number {

    let counter: Map<string, number> = new Map();
    s.split("").forEach(x => {
        if (counter.has(x)) {
            counter.set(x, counter.get(x)! + 1);
        } else {
            counter.set(x, 1);
        }
    });
    for (let i: number = 0; i < s.length; i++) {
        if (counter.get(s[i]) === 1) {
            return i;
        }
    }
    return -1;
}

