function useCustomCompareEffect(callback: EffectCallback, deps?: DependencyList, compareFn: (a: DependencyList, b: DependencyList) => boolean = isEqual) {
    const prevDeps = useRef<readonly any[] | null |undefined>(null)

    useEffect(() => {
        if (prevDeps.current && deps) {
            const isEqual = compareFn(prevDeps.current, deps);
            if (isEqual) {
                return;
            } else {
                return callback();
            }
        } else {
            return callback();
        }
    });
    useEffect(()=> {
        prevDeps.current = deps;
    })
}

