async function getStars(opts: StarsOpts): Promise<StarsResult> {
  let repos;
  if (opts.repo) {
    repos = [{owner: opts.org, name: opts.repo}];
  } else {
    repos = await getOrgRepos(opts.org);
  }

  const fetches = [];

  for (const {owner, name} of repos) {
    fetches.push(fetchStarsForRepo(owner, name));
  }

  const allStars = [];
  for (const fetch of fetches) {
    allStars.push(...await fetch);
  }

  return new StarsResult(allStars);
}

function loopOnPartialChunks_<R, E, A, R1, E1, A1>(
  self: Stream<R, E, A>,
  f: (a: Chunk.Chunk<A>, emit: (a: A1) => T.UIO<void>) => T.Effect<R1, E1, boolean>
): Stream<R & R1, E | E1, A1> {
  return loopOnChunks_(self, (chunk) =>
    C.unwrap(
      T.suspend(() => {
        let outputChunk = Chunk.empty<A1>()
        return T.catchAll_(
          T.map_(
            f(chunk, (a: A1) =>
              T.succeedWith(() => {
                outputChunk = Chunk.append_(outputChunk, a)
              })
            ),
            (cont) => C.chain_(C.write(outputChunk), () => C.end(cont))
          ),
          (failure) =>
            T.succeedWith(() => {
              if (Chunk.isEmpty(outputChunk)) {
                return C.fail(failure)
              } else {
                return C.chain_(C.write(outputChunk), () => C.fail(failure))
              }
            })
        )
      })
    )
  )
}

