function HashDecorator(target, propertyKey: string, descriptor: PropertyDescriptor): any {
    var oldValue = descriptor.value;

    descriptor.value = function () {
        let hashValue = `hash of "${target.id}" and "${target.name}"`;
        Object.defineProperty(target, "hash", { value: hashValue, configurable: true, writable: true, enumerable: true });
        let returningValue = oldValue.apply(null, arguments);
        return returningValue;
    };

    return descriptor;
}

function process(p: JSXChildrenProps | undefined): (VirtualChildrenData | string | number | undefined)[] {
  if (!p) {
    return []
  }
  if (Array.isArray(p)) {
    return p.map(process).flat()
  } else {
    const children: any[] = []

    if (!p.props || !p.__virtualTagName) {
      return [p] as any
    }
    ; (p.props.children || []).forEach(c => {
      if (Array.isArray(c)) {
        c.filter(notUndefined).forEach(cc => children.push(...process(cc)))
      } else if (typeof c !== 'object') {
        return children.push(c)
      } else {
        children.push(...process(c))
      }
    })
    const attrs = { ...p.props }
    delete attrs.children
    return [
      {
        children: children.filter(notUndefined),
        attrs,
        tagName: p.__virtualTagName
      }
    ]
  }
}

function loginFacebook(accessToken: string) {
  console.log("Redux action get access token: " + accessToken);
  return (dispatch: Dispatch<any>) => {
    // dispatch(loginSuccess());
    return axios
      .post<{
        accessToken: string;
        name: string;
        email: string;
        token: string;
        message: string;
      }>(`${Config.API_URL}/api/login/facebook`, {
        access_token: accessToken
      })
      .then(response => {
        if (response.data == null) {
          dispatch(loginFailure("Unknown Error"));
        } else if (!response.data.token) {
          // If there was a problem, we want to
          // dispatch the error condition
          dispatch(loginFailure(response.data.message || ""));
        } else {
          // If login was successful, set the token in local storage
          AsyncStorage.setItem("token", response.data.token);
          // Dispatch the success action
          // dispatch(loginSuccess());
          dispatch(loginSuccess(response.data.name, response.data.email));
        }
      })
      .catch(err => console.log("Error: ", err));
  };
}

