function filter_<A>(self: Chunk.Chunk<A>, f: (a: A) => boolean): Chunk.Chunk<A> {
  concrete(self)

  switch (self._typeId) {
    case ArrTypeId: {
      const arr = self.arrayLike()
      const len = arr.length
      let i = 0
      let builder = Chunk.empty<A>()
      while (i < len) {
        const elem = arr[i]!
        if (f(elem)) {
          builder = Chunk.append_(builder, elem)
        }
        i++
      }
      return builder
    }
    default: {
      const iterator = self.arrayLikeIterator()
      let next
      let builder = Chunk.empty<A>()
      while ((next = iterator.next()) && !next.done) {
        const array = next.value
        const len = array.length
        let i = 0
        while (i < len) {
          const a = array[i]!
          if (f(a)) {
            builder = Chunk.append_(builder, a)
          }
          i++
        }
      }

      return builder
    }
  }
}

function last<TSource>(this: Enumerable<TSource>, predicate?: (item: TSource) => boolean): TSource {
  if (predicate) {
    let result: TSource;
    let found = false;
    for (let item of this) {
      if (predicate(item)) {
        result = item;
        found = true;
      }
    }
    if (!found) {
      throw new Error("No items matched the predicate");
    }
    return result!;
  } else {
    let found = false;
    let last: TSource;
    for (last of this) {
      found = true;
    }
    if (!found) {
      throw new Error("Sequence was empty");
    }
    return last!;
  }
}

