function loopOnChunks_<R, E, A, R1, E1, A1>(
  self: Stream<R, E, A>,
  f: (
    a: Chunk.Chunk<A>
  ) => C.Channel<R1, E | E1, Chunk.Chunk<A>, unknown, E | E1, Chunk.Chunk<A1>, boolean>
): Stream<R & R1, E | E1, A1> {
  const loop: C.Channel<
    R1,
    E | E1,
    Chunk.Chunk<A>,
    unknown,
    E | E1,
    Chunk.Chunk<A1>,
    boolean
  > = C.readWithCause(
    (chunk) => C.chain_(f(chunk), (cont) => (cont ? loop : C.end(false))),
    C.failCause,
    (_) => C.end(false)
  )
  return new Stream(self.channel[">>>"](loop))
}

