function getMethodNames(objectOrKlass: any): string[] {
  let keys: string[] = []

  if (typeof objectOrKlass === 'function') {
    return Object.getOwnPropertyNames(objectOrKlass.prototype).filter(
      (key: string) => {
        if (key === 'constructor') {
          return false
        }
        return true
      }
    )
  } else if (objectOrKlass.constructor.name === 'Object') {
    keys = Object.keys(objectOrKlass)
  } else {
    keys = Object.getOwnPropertyNames(objectOrKlass.constructor.prototype)
    Object.keys(objectOrKlass).forEach(key => {
      if (!keys.includes(key)) {
        keys.push(key)
      }
    })
  }

  return keys.filter((key: string) => {
    if (key === 'constructor') {
      return false
    }

    if (typeof objectOrKlass[key] !== 'function') {
      return false
    }
    return true
  })
}

function elementListener(document: Document, selector: string): TimedPromise<Element> {
	return new TimedPromise(10 * 1000, (resolve: any, reject: any) => {
		var el = document.querySelector(selector);
		if (el != null) {
			resolve(el);
			return;
		}

		var observer = new MutationObserver((mutations) => {
			mutations.forEach((mutation) => {
				if (!mutation.addedNodes) return;
				for (let i = 0; i < mutation.addedNodes.length; i++) {
					try {
						const node = mutation.addedNodes[i];
						if (node.nodeType == 1) {
							if ((node as Element).matches(selector)) {
								resolve(node as Element);
								observer.disconnect();
							}
						}
					} catch (e) {}
				}
			});
		});

		observer.observe(document.body, {
			childList: true,
			subtree: true,
			attributes: false,
			characterData: false
		});
	});
}

