function readGitIgnore(dir: string) {
  const filepath = path.join(dir, '.gitignore');
  if (!fs.pathExistsSync(filepath)) {
    return [];
  }

  return fs.readFileSync(filepath, 'utf-8')
    .split('\n')
    .filter(x => x?.trim() !== '')
    .filter(x => !x.startsWith('#') && !x.startsWith('!'))
    .map(x => x.replace(/^\//, '')) // remove "/" prefix
    .map(x => `${x}\n${x}/**`)
    .join('\n')
    .split('\n');
}

function useFullscreen(
  target: Ref<HTMLElement | null> | HTMLElement,
  options?: Options
): ToRefs<Result> {
  const { onExitFull, onFull } = options || {}
  const isScreenfull = (arg: any): arg is Screenfull => arg.isEnabled
  const result: Result = {
    isFullscreen: isScreenfull(screenfull)
      ? ref(screenfull.isFullscreen)
      : ref(false),
    setFull: () => {},
    exitFull: () => {},
    toggleFull: () => {},
  }

  safeOnMounted(() => {
    const HtmlTarget = getTargetElement(target)
    if (HtmlTarget) {
      result.setFull = () => {
        if (screenfull.isEnabled && !result.isFullscreen.value) {
          result.isFullscreen.value = true
          screenfull.request(HtmlTarget)
          onFull && onFull()
        }
      }
      result.exitFull = () => {
        if (screenfull.isEnabled) {
          if (result.isFullscreen.value) {
            result.isFullscreen.value = false
            screenfull.exit()
            onExitFull && onExitFull()
          }
        }
      }
      result.toggleFull = () => {
        if (screenfull.isEnabled) {
          screenfull.toggle(HtmlTarget).then(() => {
            result.isFullscreen.value = !result.isFullscreen.value
            if (result.isFullscreen.value) {
              onFull && onFull()
            } else {
              onExitFull && onExitFull()
            }
          })
        }
      }
    }
  })
  return toRefs(result)
}

