function hueToRgb(t1: number, t2: number, h: number): number {
  h = (h + 360) % 360;

  if (h < 60) {
    return ((t2 - t1) * h) / 60 + t1;
  } else if (h < 180) {
    return t2;
  } else if (h < 240) {
    return ((t2 - t1) * (240 - h)) / 60 + t1;
  } else {
    return t1;
  }
}

