async function waitForBuild(
  projectId: string,
  id: string,
  client: CloudBuildClient
): Promise<google.devtools.cloudbuild.v1.IBuild> {
  // This loop is set to equal a total of 3 hours, which should
  // match the timeout in cloud-build/update-pr.yaml's timeout
  for (let i = 0; i < TOTAL_PINGS; i++) {
    const [build] = await client.getBuild({projectId, id});
    if (build.status !== 'WORKING' && build.status !== 'QUEUED') {
      return build;
    }
    // Wait a few seconds before checking the build status again:
    await new Promise(resolve => {
      const delay = PING_DELAY;
      setTimeout(() => {
        return resolve(undefined);
      }, delay);
    });
  }
  throw new TimeoutError(`timed out waiting for build ${id}`);
}

function ReportExceptionsToConsole() {
    return Mutator.define({
        options: { 
            validTargets: ['method'] 
        },

        invoke(site) {
            let originalMethod : Function = site.propertyDescriptor.value;
            site.propertyDescriptor.value = function (...args) {
                let type : Function;
                let isStatic : boolean = false;

                if (typeof site.target === 'function') {
                    type = site.target;
                    isStatic = true;
                } else {
                    type = site.target.constructor;
                    isStatic = false;
                }

                let typeName : string;
                let sep : string = '.';

                if (isStatic)
                    sep = '#';

                typeName = type.name;

                try {
                    return originalMethod.apply(this, args);
                } catch (e) {
                    console.error(`Error occurred during ${typeName}${sep}${site.propertyKey}():`);
                    console.error(e);
                    throw e;
                }
            };
        }
    });
}

