function convoSegmentPath(content: _ConvoSegmentPath): ConvoSegmentPath {
    if (content.length === 0) {
        throw new Error(`Empty convo segment path is not allowed`)
    }
    const parentModules: ConvoModuleId[] = content
        .slice(0, content.length - 1)
        .map(unverified => convoModuleId(unverified))
    const id: ConvoSegmentId = convoSegmentId(content[content.length - 1])
    const relativePath = parentModules.length > 0
    return relativePath
        ? {
              id,
              parentModules,
          }
        : {
              id,
          }
}

function intoASM(
  insts: Inst[],
  data: Uint8Array,
  emitAddr = false,
  emitOp = false,
): string[] {
  const result = [];
  const labels = sortIntoLabels(insts, data);
  for (const label in labels) {
    result.push(label + ":");
    const insts = labels[label];
    for (const inst of insts) {
      let asm = "  " + instToASM(inst);
      if (emitAddr || emitOp) {
        asm = asm.padEnd(30, " ");
        let op = emitOp ? (data[inst.at] << 8 | data[inst.at + 1]) : undefined;
        asm += `; ${
          op !== undefined ? `0x${op.toString(16).padStart(4, "0")} ` : ""
        }${
          emitAddr
            ? `@ 0x${(inst.at + 0x200).toString(16).padStart(4, "0")}`
            : ""
        }`;
      }
      result.push(asm);
    }
  }
  return result;
}

