function collapseNodes(root: TreeNode, graphCollapse?: unknown) {
    const streamlineOrCollapse = graphCollapse === "s" ? streamline : collapseAllChildren;
    if (graphCollapse !== "n") {
        treeDescription.visitTreeNodes(
            root,
            d => {
                switch (d.name) {
                    case "condition":
                    case "conditions":
                    case "datasource":
                    case "expressions":
                    case "field":
                    case "groupbys":
                    case "group-bys":
                    case "imports":
                    case "measures":
                    case "column-names":
                    case "replaced-columns":
                    case "renamed-columns":
                    case "new-columns":
                    case "metadata-record":
                    case "metadata-records":
                    case "orderbys":
                    case "order-bys":
                    case "filter":
                    case "predicate":
                    case "restrictions":
                    case "runquery-columns":
                    case "selects":
                    case "schema":
                    case "tid":
                    case "top":
                    case "aggregates":
                    case "join-conditions":
                    case "join-condition":
                    case "arguments":
                    case "function-node":
                    case "type":
                    case "tuples":
                        streamlineOrCollapse(d);
                        return;
                }
                switch (d.class) {
                    case "relation":
                        collapseAllChildren(d);
                        return;
                }
            },
            function(d): TreeNode[] {
                return d.children && d.children.length > 0 ? d.children.slice(0) : [];
            },
        );
    }
}

