function many<P>(parser: Parser<P>): Parser<P[]> {
  return fromGenerator(function* many() {
    var results: P[] = [];
    while (true) {
      const state = yield 0;
      try {
        var result = yield* parser;
      } catch (e) {
        yield state;
        return results;
      }
      results.push(result);
    }
  }, `many(${parser.parserName})`);
}

