                'Content-Security-Policy': ['default-src \'self\'; style-src \'self\' \'unsafe-inline\'; img-src \'self\''],
            },
        });
    });

    userContentWindow.webContents.session.setPermissionRequestHandler((webContents, permission, callback) => {
