    for (let group of data) {
        let keyValues: any[] = [];
        for (let section of group) {
            keyValues.push(section[key.toString()]);
        }
        let unique: any[] = keyValues.filter((val, i, arr) => arr.indexOf(val) === i);
        for (let s of group) {
            s[applyKey] = unique.length;
        }
    }
    let result: any[] = [];
    for (let i of data) {
        result.push(i[0]);
    }
    return result;
