function isTopRight(grid) {

  let found;
  let foundPiece;
  let col;

  // Here, we take successive diagonals, defined by the location of their "base",
  // meaning the column where they meet the ground.
  // The initial baseCol is a negative number, representing that the diagonal starts off
  // the board. These diagonals intersect the board, nonetheless.
  for (
    let baseCol = matchReq - numRows;
    baseCol < numCols - (matchReq - 1);
    baseCol++
  ) {

      found = 0;
      foundPiece = 0;
      col = baseCol - 1; // Subtracting 1 to compensate for incrementing col at
                         // the beginning of the loop

      // Here we work our way *DOWN* the current diagonal
      for (let row = numRows - 1; row >= 0; row--) {
        col++;

        // Ensure that the given column and row are on the board
        if (col >= 0 && col < numCols && row < numRows) {

          let piece = grid[col][row];

          if(!piece) {
            found = 0;
          }

          if (!!piece && (piece === foundPiece || !foundPiece) && (++found) === matchReq) {
            return true;
          }

          foundPiece = piece;

      }
    }
  }

  return false;
}

function chooseMedia(options: Taro.chooseMedia.Option) {
  const mediaid = 'taroChooseMedia';
  const { success, fail, sourceType, count } = options;

  const res: Taro.chooseMedia.SuccessCallbackResult = {
    tempFiles: [],
    type: "mdeia",
    /** 调用结果 */
    errMsg: 'chooseMedia:ok',
  }
  let taroChooseVideo = document.getElementById(mediaid) as HTMLInputElement | null
  if (!taroChooseVideo) {
    let obj = document.createElement('input')
    obj.setAttribute('type', 'file')
    obj.setAttribute('id', mediaid)
    obj.setAttribute('accept', 'image/*, video/*')
    obj.setAttribute('style', 'position: fixed; top: -4000px; left: -3000px; z-index: -300;')
    taroChooseVideo = document.body.appendChild(obj)!
    taroChooseVideo.multiple = (!!options.count && options.count > 1)
  } else {
    taroChooseVideo.multiple = (!!options.count && options.count > 1)
  }
  let taroChooseVideoCallback
  const taroChooseVideoPromise = new Promise<Taro.chooseMedia.SuccessCallbackResult>(resolve => {
    taroChooseVideoCallback = resolve
  })
  let TaroMouseEvents = document.createEvent('MouseEvents')
  TaroMouseEvents.initEvent('click', true, true)
  taroChooseVideo.dispatchEvent(TaroMouseEvents)
  taroChooseVideo.onchange = function (e) {
    Promise.all(
      [...(taroChooseVideo!.files || [])].map(item => {
        return new Promise<Taro.chooseMedia.ChooseMedia>((resolve, reject) => {
          let blob = new Blob([item], {
            type: item.type
          })
          let url = URL.createObjectURL(blob)
          if (item.type.includes("image")) {
            // image
            const image = new Image();
            image.onload = function () {
              resolve({
                /** 本地临时文件路径 (本地路径) */
                tempFilePath: url,
                /** 本地临时文件大小，单位 B */
                size: item.size,
                /** 视频的时间长度 */
                duration: -1,
                /** 视频的高度 */
                height: image.naturalHeight,
                /** 视频的宽度 */
                width: image.naturalWidth,
                /** 视频缩略图临时文件路径 */
                thumbTempFilePath: url
              })
              image.remove()
            }
            image.src = url;
          } else {
            // video
            const VideoEl = document.createElement('video');
            VideoEl.onloadedmetadata = function () {
              resolve({
                /** 本地临时文件路径 (本地路径) */
                tempFilePath: url,
                /** 本地临时文件大小，单位 B */
                size: item.size,
                /** 视频的时间长度 */
                duration: VideoEl.duration,
                /** 视频的高度 */
                height: VideoEl.videoHeight,
                /** 视频的宽度 */
                width: VideoEl.videoWidth,
                /** 视频缩略图临时文件路径 */
                thumbTempFilePath: ''
              })
              VideoEl.remove()
            }
            VideoEl.src = url;
          }
        })
      })
    ).then(tempFiles => {
      res.tempFiles = tempFiles.slice(0, count)
      typeof success === 'function' && success(res)
      // typeof complete === 'function' && complete(res)
      taroChooseVideoCallback(res)
      taroChooseVideo!.value = ''
    })
  }
  return taroChooseVideoPromise
}

