async function findTemporaryWorkTrees(
  repository: Repository
): Promise<ReadonlyArray<LinkedWorkTree>> {
  const workTrees = await listWorkTrees(repository)

  // always exclude the first entry as that will be "main" worktree and we
  // should not even look at it funny
  const candidateWorkTrees = workTrees.slice(1)

  return candidateWorkTrees.filter(t => {
    // NOTE:
    // we can't reliably check the full path here because Git seems to be
    // prefixing the temporary paths on macOS with a `/private` prefix, and
    // NodeJS doesn't seem to include this when we ask for the temporary
    // directory for the OS
    const directoryName = Path.basename(t.path)
    return directoryName.startsWith(KactusWorkTreePrefix)
  })
}

function CreateCryptor(rgbKey, rgbIV, encrypt) {
			const key = rgbKey ? rgbKey : this.Key;
			const newKey = new System.Byte(key.length);
			System.Buffer.BlockCopy(key, 0, newKey, 0, key.length);
			const iv = rgbIV ? rgbIV : this.IV;
			const newIv = new System.Byte(iv.length);
			System.Buffer.BlockCopy(iv, 0, newIv, 0, iv.length);
			const algorithm = new System.Security.Cryptography.RijndaelManaged();
			algorithm.Key = newKey;
			algorithm.IV = newIv;
			algorithm.Mode = this.Mode;
			algorithm.Padding = this.Padding;
			const cryptor = new System.Security.Cryptography.ICryptoTransform(algorithm, encrypt);
			return cryptor;
		}

