function expand(exp: BelT): BelT {
  let lastExp: BelT = null;

  while (true) {
    /*
    pr("e", exp);
    pr("last e", lastExp);
    */

    if (equal(exp, lastExp)) {
      // finished expanding
      return exp;
    }

    lastExp = exp;

    if (pair(exp)) {
      let p: Pair = exp as Pair;

      /*
      if (number(car(p))) {
        exp = join(sym("nth"), p);
        continue;
      }
      */

      while (p !== null) {
        xar(p, expand(car(p)));

        const d: BelT = cdr(p);

        if (d === null || pair(d)) {
          p = d as Pair;
          continue;
        }

        // improper?
        xdr(p, expand(d));
        break;
      }
    } else {
      if (symbol(exp)) {
        exp = expandSymbol(exp as symbol);
        continue;
      }
    }
  }
}

