function skip<T>(numElements: number): (source: IterableIterator<T>) => IterableIterator<T> {
    return function* (source: IterableIterator<T>) {
        let counter = 0;
        for (const item of source) {
            if (counter++ >= numElements) {
                yield item;
            }
        }
    };
}

