function digestIE(msg: ArrayBuffer) {
  const algo = 'SHA-256';
  return new Promise((resolve, reject) => {
    let ieOp = _crypto.subtle.digest({ name: algo }, msg);
    ieOp.onerror = () => {
      reject(new Error(`Could not create hash.`));
    };
