function deleteFromCache(emailToDelete: EmailAddressWrapper): boolean {
    let i = 0;
    let match = false;
    if (rcStore.recipientCache) {
        while (!match && i < rcStore.recipientCache.length) {
            let email = rcStore.recipientCache[i].EmailAddress;
            if (
                (email.EmailAddress && email.EmailAddress == emailToDelete.EmailAddress) ||
                (email.Name && email.Name == emailToDelete.Name)
            ) {
                match = true;
                rcStore.recipientCache.splice(i, 1);
            } else {
                i++;
            }
        }
    }

    if (emailToDelete.EmailAddress) {
        addSessionMaskedRecipient(emailToDelete.EmailAddress);
    } else if (emailToDelete.Name) {
        addSessionMaskedRecipient(emailToDelete.Name);
    }

    return match;
}

function checkAddFolderToPath(exeFolder: string, terminalType: TerminalType, prepend = true) {
  const oldPathValue = process.env['PATH'] || (IsWindows ? '%PATH%' : '$PATH');
  const paths = oldPathValue.split(IsWindows ? ';' : ':');
  const trimTailRegex = IsWindows ? new RegExp('[\\s\\\\]+$') : new RegExp('/$');
  const foundFolders = IsWindows
    ? paths.filter(a => a.trim().replace(trimTailRegex, '').toLowerCase() === exeFolder.toLowerCase())
    : paths.filter(a => a.replace(trimTailRegex, '') === exeFolder);

  if (foundFolders.length > 0) {
    return false;
  }

  const separator = getPathEnvSeparator(terminalType);
  const newValue = prepend
    ? exeFolder + separator + oldPathValue
    : oldPathValue + separator + exeFolder;

  process.env['PATH'] = newValue;

  return true;
}

