function getDecoratorSettings(tree: Tree, filePath: string, decorator: string): ts.Node {
    const fileContent = getFileContent(tree, filePath);
    let sourceFile: ts.SourceFile = ts.createSourceFile('temp.ts', fileContent, ts.ScriptTarget.Latest);

    let toReturn: ts.Node | undefined;

    sourceFile.getChildren().forEach(node => {
        node.getChildren().filter(node => ts.isClassDeclaration(node)).forEach((node: ts.Node) => {
            if (node.decorators) {
                node.forEachChild(node => node.forEachChild(decoratorNode => {
                    if (decoratorNode.kind === ts.SyntaxKind.CallExpression) {
                        decoratorNode.forEachChild(node => {
                            if (ts.isIdentifier(node) && node.escapedText === decorator) {
                                toReturn = decoratorNode;
                            }
                        })
                    }
                }))
            }
        });
    });
    if (toReturn) {
        return toReturn;
    }
    throw new NgToolkitException(`Can't find decorator ${decorator} in ${filePath}`, {fileContent: fileContent});
}

function getTerminalTypeFromExePath(terminalExePath: string = TerminalExePath): TerminalType {
  if (IsLinux) {
    return TerminalType.LinuxBash;
  } else if (IsWSL) {
    return TerminalType.WslBash;
  } else if (/cmd.exe$/i.test(terminalExePath)) {
    return TerminalType.CMD;
  } else if (/PowerShell.exe$/i.test(terminalExePath)) {
    return TerminalType.PowerShell;
  } else if (/Cygwin.*?bash.exe$/i.test(terminalExePath)) {
    return TerminalType.CygwinBash;
  } else if (/System(32)?.bash.exe$/i.test(terminalExePath)) {
    return TerminalType.WslBash;
  } else if (/MinGW.*?bash.exe$/i.test(terminalExePath) || /Git.*?bin.*?bash.exe$/i.test(terminalExePath)) {
    return TerminalType.MinGWBash;
  } else if (/bash.exe$/.test(terminalExePath)) {
    return TerminalType.WslBash;
  } else if (IsWindows) {
    return TerminalType.PowerShell; // TerminalType.CMD;
  } else {
    return TerminalType.LinuxBash;
  }
}

