function findGCDLoop(m: number, n: number, iterations: number = 0): number {
    const M: number = m;
    const N: number = n;

    // Step F1
    m = m % n;
    iterations++;

    // Step F2
    while (m !== 0) {
        // Step F3
        n = n % m;

        // Step F4
        if (n === 0) {
            printAnswer('findGCDLoop', M, N, m, iterations);
            return m;
        }

        // Step F1
        m = m % n;
        iterations++;
    }

    printAnswer('findGCDLoop', M, N, n, iterations);
    return n;
}

function normalizeDynamicRouteParams(
    params: ParsedUrlQuery,
    ignoreOptional?: boolean
  ) {
    let hasValidParams = true
    if (!defaultRouteRegex) return { params, hasValidParams: false }

    params = Object.keys(defaultRouteRegex.groups).reduce((prev, key) => {
      let value: string | string[] | undefined = params[key]

      if (typeof value === 'string') {
        value = normalizeRscPath(value, true)
      }
      if (Array.isArray(value)) {
        value = value.map((val) => {
          if (typeof val === 'string') {
            val = normalizeRscPath(val, true)
          }
          return val
        })
      }

      // if the value matches the default value we can't rely
      // on the parsed params, this is used to signal if we need
      // to parse x-now-route-matches or not
      const defaultValue = defaultRouteMatches![key]
      const isOptional = defaultRouteRegex!.groups[key].optional

      const isDefaultValue = Array.isArray(defaultValue)
        ? defaultValue.some((defaultVal) => {
            return Array.isArray(value)
              ? value.some((val) => val.includes(defaultVal))
              : value?.includes(defaultVal)
          })
        : value?.includes(defaultValue as string)

      if (
        isDefaultValue ||
        (typeof value === 'undefined' && !(isOptional && ignoreOptional))
      ) {
        hasValidParams = false
      }

      // non-provided optional values should be undefined so normalize
      // them to undefined
      if (
        isOptional &&
        (!value ||
          (Array.isArray(value) &&
            value.length === 1 &&
            // fallback optional catch-all SSG pages have
            // [[...paramName]] for the root path on Vercel
            (value[0] === 'index' || value[0] === `[[...${key}]]`)))
      ) {
        value = undefined
        delete params[key]
      }

      // query values from the proxy aren't already split into arrays
      // so make sure to normalize catch-all values
      if (
        value &&
        typeof value === 'string' &&
        defaultRouteRegex!.groups[key].repeat
      ) {
        value = value.split('/')
      }

      if (value) {
        prev[key] = value
      }
      return prev
    }, {} as ParsedUrlQuery)

    return {
      params,
      hasValidParams,
    }
  }

