function parseNote(text: string): DenormalizedNote {
  let note = { ...newDenormalizedNote };
  note.attributes = { ...newDenormalizedNote.attributes };

  let divisorIdx = text.lastIndexOf(divisor);

  if (divisorIdx !== -1) {
    note.attributes = {
      ...note.attributes,
      ...JSON.parse(text.slice(divisorIdx + divisor.length))
    };
    note.attributes.content = text.slice(0, divisorIdx);
  } else {
    note.attributes.content = text;
  }

  return note;
}

async function saveArchiveMetadata(date: Moment, metadata: ArchiveMetadata) {
  const archiveMetadata: any = {
    files: [],
    message_num: 0,
    hours: {},
  }

  for (const hour in metadata.hours) {
    if (metadata.hours.hasOwnProperty(hour)) {
      const v = metadata.hours[hour]
      archiveMetadata.files = archiveMetadata.files.concat(v.files)
      archiveMetadata.message_num += v.messageNum
      archiveMetadata.hours[hour] = {
        files: v.files,
        message_num: v.messageNum,
      }
    }
  }

  const filename = `metadata.json`
  const bucket = storage.bucket()
  const file = bucket.file(`/public/archives/${date.format('YYYY/MM/DD')}/${filename}`)
  await file.save(JSON.stringify(archiveMetadata), {
    gzip: true,
    contentType: 'application/json',
  })

  return archiveMetadata
}

function applyKernel3x3(kernel: number[], grayscale: Uint8Array, width: number, height: number) {

