function itemSize(item: LayoutItem, parent: LayoutItem | null, sizes: LayoutItemSizes, isContainer: boolean): Size {
	const parentResizableRight = !!parent && parent.resizableRight;
	const parentResizableBottom = !!parent && parent.resizableBottom;

	const rightGap = !isContainer && (item.resizableRight || parentResizableRight) ? dragBarThickness : 0;
	const bottomGap = !isContainer && (item.resizableBottom || parentResizableBottom) ? dragBarThickness : 0;

	return {
		width: sizes[item.key].width - rightGap,
		height: sizes[item.key].height - bottomGap,
	};
}

function runProgram(program: number[], inputBuffer: number[]): Machine {
	const machine = {
		memory: program,
		inputBuffer,
		outputBuffer: [],
		instructionCounter: 0,
		didJump: false,
	};

	while (machine.memory[machine.instructionCounter] !== 99) {
		const advance = execCommand(machine);
		if (machine.didJump) {
			machine.didJump = false;
		} else {
			machine.instructionCounter += advance;
		}
	}

	console.log(`Program execution complete\n\n`);

	return machine;
}

