function validate(validationRules: ValidationRulesMap, data: any): ValidationResult {
  const map = new Map();
  let isValid = true;

  validationRules.forEach((rules, key) => {
    const value = R.view(R.lensPath(key.split('.')))(data);
    const firstInvalidRule = rules.find((item: any) => !item.rule(value, data));
    let validationStatus;

    if (firstInvalidRule) {
      isValid = false;
      validationStatus = {
        status: 'invalid',
        message: firstInvalidRule.message,
      }
    } else {
      validationStatus = {
        status: 'valid',
      }
    }

    map.set(key, validationStatus);
  });

  return {
    fields: map,
    isValid: isValid, 
  };
}

