function getRFC2822Date(date = new Date(), useUtc = false) {
	if (useUtc) {
		return getRFC2822DateUTC(date);
	}

	const dates = date
		.toString()
		.replace('GMT', '')
		.replace(/\s\(.*\)$/, '')
		.split(' ');

	dates[0] = dates[0] + ',';

	const day = dates[1];
	dates[1] = dates[2];
	dates[2] = day;

	return dates.join(' ');
}

async function fetchStarsForRepo(owner: string, name: string): Promise<Star[]> {
  const stars: Star[] = [];

  const results = github().cursorQuery<StarsQuery, StarsQueryVariables>(
      starsQuery,
      {owner, name},
      (data) => data.repository && data.repository.stargazers);

  for await (const data of results) {
    const repo = data.repository;
    if (!repo) {
      continue;
    }
    for (const star of repo.stargazers.edges || []) {
