function transferFromPurseToPurse(sourcePurse: URef, targetPurse: URef, amount: U512, id: Ref<u64> | null = null): Error | null {
    let sourceBytes = sourcePurse.toBytes();
    let targetBytes = targetPurse.toBytes();
    let amountBytes = amount.toBytes();

    let optId: Option;
    if (id !== null) {
        const idValue = (<Ref<u64>>id).value;
        optId = new Option(arrayToTyped(toBytesU64(idValue)));
    }
    else {
        optId = new Option(null);
    }
    const idBytes = optId.toBytes();

    let ret = externals.transfer_from_purse_to_purse(
        sourceBytes.dataStart,
        sourceBytes.length,
        targetBytes.dataStart,
        targetBytes.length,
        amountBytes.dataStart,
        amountBytes.length,
        idBytes.dataStart,
        idBytes.length,
    );

    return Error.fromResult(ret);
}

function integer(a: IBigFloat): IBigFloat {
  // The integer function is like the normalize function except that it throws
  // away significance. It discards the digits after the decimal point.

  const { coefficient, exponent } = a;

  // If the exponent is zero, it is already an integer.

  if (exponent === 0) {
    return a;
  }

  // If the exponent is positive,
  // multiply the coefficient by 10 ** exponent.

  if (exponent > 0) {
    return make_big_float(
      JSBI.multiply(
        coefficient,
        JSBI.exponentiate(BIGINT_TEN, JSBI.BigInt(exponent))
      ),
      0
    );
  }

  // If the exponent is negative, divide the coefficient by 10 ** -exponent.
  // This truncates the unnecessary bits. This might be a zero result.

  return make_big_float(
    JSBI.divide(
      coefficient,
      JSBI.exponentiate(BIGINT_TEN, JSBI.BigInt(-exponent))
    ),
    0
  );
}

function validate(input: ValidationInput) {
  let result: ValidationResult = {
    isValid: true,
    errorMessages: []
  };

  if (input.required) {
    const isValid = input.value.toString().trim().length > 0
    if (!isValid) result.errorMessages.push(`[Validation]: ${input.name} is required`);
    result.isValid = result.isValid && isValid;
  }

  if (input.minLength != null && typeof input.value === 'string') {
    const isValid =
      input.value.length >= input.minLength;
    if (!isValid) result.errorMessages.push(`[Validation]: min length of the ${input.name} is ${input.minLength}, but provided value with length: ${input.value.length}`);
    result.isValid = result.isValid && isValid;
  }

  if (input.maxLength != null && typeof input.value === 'string') {
    const isValid =
      input.value.length <= input.maxLength;
    if (!isValid) result.errorMessages.push(`[Validation]: max length of the ${input.name} is ${input.minLength}, but provided value with length: ${input.value.length}`);
    result.isValid = result.isValid && isValid;
  }

  if (input.min != null && typeof input.value === 'number') {
    const isValid =
      input.value >= input.min;
    if (!isValid) result.errorMessages.push(`[Validation]: min of the ${input.name} is ${input.min}, but provided value is: ${input.value}`);
    result.isValid = result.isValid && isValid;
  }

  if (input.max != null && typeof input.value === 'number') {
    const isValid =
      input.value <= input.max;
    if (!isValid) result.errorMessages.push(`[Validation]: max of the ${input.name} is ${input.max}, but provided value is: ${input.value}`);
    result.isValid = result.isValid && isValid;
  }



  return result;
}

function equals(x, y): boolean {
  if (x === y) {
    return true;
  }
  // if both x and y are null or undefined and exactly the same
  if (!(x instanceof Object) || !(y instanceof Object)) {
    return false;
  }
  // if they are not strictly equal, they both need to be Objects
  if (x.constructor !== y.constructor) {
    return false;
  }
  // they must have the exact same prototype chain, the closest we can do is
  // test there constructor.

  for (const p in x) {
    if (!x.hasOwnProperty(p)) {
      continue;
    }
    // other properties were tested using x.constructor === y.constructor
    if (!y.hasOwnProperty(p)) {
      return false;
    }
    // allows to compare x[ p ] and y[ p ] when set to undefined
    if (x[p] === y[p]) {
      continue;
    }
    // if they have the same strict value or identity then they are equal
    if (typeof x[p] !== 'object') {
      return false;
    }
  }
  for (const p in y) {
    if (y.hasOwnProperty(p) && !x.hasOwnProperty(p)) {
      return false;
    }
  }
  return true;
}

