function isEqual(collectionA: Scope[], collectionB: Scope[]): boolean {
  const simplifiedCollectionA = simplify(collectionA);
  const simplifiedCollectionB = simplify(collectionB);
  if (simplifiedCollectionA.length !== simplifiedCollectionB.length) {
    return false;
  }

  for (const [iScope, scopeA] of simplifiedCollectionA.entries()) {
    const scopeB = simplifiedCollectionB[iScope];
    if (scopeA.length !== scopeB.length) {
      return false;
    }

    for (const [iDomain, domainA] of scopeA.entries()) {
      const domainB = scopeB[iDomain];
      if (domainA.length !== domainB.length) {
        return false;
      }

      for (const [iSegment, segmentA] of domainA.entries()) {
        const segmentB = domainB[iSegment];
        if (segmentA !== segmentB) {
          return false;
        }
      }
    }
  }

  return true;
}

function useToastAnnounce(announce: Announce) {
  const activeRef = React.useRef(true);
  const cleanupRef = React.useRef<() => void>(() => undefined);
  const announceToast = React.useCallback<Announce>(
    (message, options) => {
      if (activeRef.current) {
        announce(message, options);
      }
    },
    [announce],
  );

  const toasterRef = React.useCallback((el: HTMLDivElement | null) => {
    if (!el) {
      cleanupRef.current();
      return;
    }

    const onFocusIn = (e: FocusEvent) => {
      if (
        isHTMLElement(e.currentTarget) &&
        e.currentTarget.contains(isHTMLElement(e.relatedTarget) ? e.relatedTarget : null)
      ) {
        return;
      }

      activeRef.current = false;
    };

    const onFocusOut = (e: FocusEvent) => {
      if (
        isHTMLElement(e.currentTarget) &&
        e.currentTarget.contains(isHTMLElement(e.relatedTarget) ? e.relatedTarget : null)
      ) {
        return;
      }

      activeRef.current = true;
    };

    el.addEventListener('focusin', onFocusIn);
    el.addEventListener('focusout', onFocusOut);

    cleanupRef.current = () => {
      el.removeEventListener('focusin', onFocusIn);
      el.removeEventListener('focusout', onFocusOut);
    };
  }, []);

  return {
    announceToast,
    toasterRef,
  };
}

