function getNextVertex(
  start: IVertex,
  end: IVertex,
  slope: number,
  stepIndex: number,
  totalStep: number,
  b: number
): IVertex {
  const { y: y1, x: x1 } = start;
  const { y: y2, x: x2 } = end;

  const xDistance = Math.abs(x1 - x2) * (stepIndex / totalStep);

  const direction = getDirection(start, end);
  let x = x1 + xDistance;

  if (direction.left) {
    x = x1 - xDistance;
  }

  const y = slope * x + b;

  return { x, y };
}

