function reducer(state: GameData = initialState, action: GameDataActions.Actions): GameData {
  const updatedGameStatus = {...state.gameStatus};

  switch (action.type) {
    case GameDataActions.LOAD_INITIAL_DATA:
      return action.payload;

    case DECREMENT_SKIP:
      updatedGameStatus.skips--;
      return {...state, gameStatus: updatedGameStatus};

    case DECREMENT_LIFE:
      updatedGameStatus.livesRemaining--;
      return {...state, gameStatus: updatedGameStatus};

    case ADD_POINTS:
      updatedGameStatus.points += POINTS_EARNED_PER_QUESTION;
      return {...state, gameStatus: updatedGameStatus};

    case SET_ANSWER:
      const updatedQuestion = state.gameQuestions[action.questionIndex];
      return {
        ...state,
        gameQuestions: {
          ...state.gameQuestions,
          [action.questionIndex]: {...updatedQuestion, isCorrectAnswer: action.correctness}
        }
      };

    default:
      return state;
  }
}

function parseKeyValue(parser: TomlParser): TomlKeyValue | undefined {
	const pos = parser.getPosition();
	let value: AnyTomlValue | undefined = undefined;
	const key: TomlKey | undefined = parseKey(parser);
	if (!key) {
		return undefined;
	}

	parser.nextToken();

	const valueToken = parser.getToken();

	switch (valueToken.type) {
		case "DoubleQuote": {
			value = parseText(parser);
			if (!value) {
				return undefined;
			}
			parser.nextToken();
			return parser.finishNode(
				pos,
				{
					type: "TomlKeyValue",
					key,
					value,
				},
			);
		}
	}

	if (!value) {
		parser.unexpectedDiagnostic({
			description: descriptions.TOML_PARSER.VALUE_NOT_RECOGNISED(key.value),
		});
		parser.nextToken();
		return undefined;
	}

	parser.nextToken();
	return undefined;
}

